/* ============ أدوات مساعدة ============ */

const fmt = (n) => new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 }).format(Math.round(n));
const fmt2 = (n) => new Intl.NumberFormat("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(n);
const emptyLine = () => ({ account: ACCOUNTS[0].name, costCenter: "", department: DEPARTMENTS[0], debit: "", credit: "", employeeId: null });
const costCenterName = (id) => COST_CENTERS.find((c) => c.id === id)?.name || "—";

/* مدة الخدمة بالسنوات/الشهور/الأيام بين تاريخين */
function serviceDuration(startStr, endStr) {
  const start = new Date(startStr);
  const end = new Date(endStr);
  let years = end.getFullYear() - start.getFullYear();
  let months = end.getMonth() - start.getMonth();
  let days = end.getDate() - start.getDate();
  if (days < 0) {
    months -= 1;
    const prevMonth = new Date(end.getFullYear(), end.getMonth(), 0);
    days += prevMonth.getDate();
  }
  if (months < 0) { years -= 1; months += 12; }
  const totalYears = years + months / 12 + days / 365;
  return { years, months, days, totalYears: Math.max(totalYears, 0) };
}

/* مكافأة نهاية الخدمة وفق نظام العمل السعودي (المادتان 84 و85) - حساب تقديري توضيحي */
function calcEOS(employee, endDate, reason) {
  const wage = employee.basicSalary + employee.housingAllowance;
  const { totalYears } = serviceDuration(employee.hireDate, endDate);
  const first5 = Math.min(totalYears, 5);
  const remaining = Math.max(totalYears - 5, 0);
  const fullReward = first5 * 0.5 * wage + remaining * 1 * wage;

  let ratio = 1;
  let ratioNote = "استحقاق كامل";
  if (reason === "resign") {
    if (totalYears < 2) { ratio = 0; ratioNote = "أقل من سنتين خدمة — لا يستحق مكافأة"; }
    else if (totalYears < 5) { ratio = 1 / 3; ratioNote = "استقالة بين 2 و5 سنوات — يستحق ثلث المكافأة"; }
    else if (totalYears < 10) { ratio = 2 / 3; ratioNote = "استقالة بين 5 و10 سنوات — يستحق ثلثي المكافأة"; }
    else { ratio = 1; ratioNote = "استقالة بعد 10 سنوات فأكثر — استحقاق كامل"; }
  }

  return { wage, totalYears, fullReward, ratio, ratioNote, finalAmount: fullReward * ratio };
}

function payrollRow(emp) {
  const gross = emp.basicSalary + emp.housingAllowance + emp.transportAllowance + (emp.otherAllowance || 0);
  const gosi = emp.gosiAmount != null && emp.gosiAmount > 0
    ? emp.gosiAmount
    : (emp.gosiApplicable ? Math.round((emp.basicSalary + emp.housingAllowance) * 0.0975) : 0);
  const advances = emp.advances || 0;
  const absence = emp.absenceDeduction || 0;
  const otherDed = emp.otherDeductions || 0;
  const totalDed = gosi + advances + absence + otherDed;
  const net = gross - totalDed;
  return { gross, gosi, advances, absence, otherDed, totalDed, net };
}

/* أدوات مساعدة لتسوية مستحقات الإجازة ومباشرة العودة */
const dailyRate = (emp) => (emp.basicSalary + emp.housingAllowance + emp.transportAllowance + (emp.otherAllowance || 0)) / 30;
const daysInMonth = (monthStr) => { const [y, m] = monthStr.split("-").map(Number); return new Date(y, m, 0).getDate(); };
const MONTH_NAMES = ["يناير", "فبراير", "مارس", "أبريل", "مايو", "يونيو", "يوليو", "أغسطس", "سبتمبر", "أكتوبر", "نوفمبر", "ديسمبر"];
const monthLabel = (monthStr) => { const [y, m] = monthStr.split("-").map(Number); return `${MONTH_NAMES[m - 1]} ${y}`; };

/* رصيد أيام الإجازة المتراكم منذ آخر عودة من إجازة (أو تاريخ المباشرة إن كانت أول إجازة) */
function accruedLeaveDays(emp, uptoDateStr) {
  const refDate = emp.lastLeaveReturnDate || emp.hireDate;
  const { totalYears } = serviceDuration(emp.hireDate, uptoDateStr);
  const annualEntitlement = totalYears >= 5 ? 30 : 21;
  const daysSinceRef = Math.max((new Date(uptoDateStr) - new Date(refDate)) / 86400000, 0);
  return { refDate, annualEntitlement, days: (daysSinceRef / 365) * annualEntitlement };
}

/* رصيد حساب الموظف (ذمم الموظفين) من واقع القيود المرحّلة فعلاً */
function employeeAccountBalance(entries, employeeId) {
  let debit = 0, credit = 0;
  entries.forEach((e) => e.lines.forEach((l) => {
    if (l.account === "ذمم الموظفين - مستحقات وإجازات" && l.employeeId === employeeId) {
      debit += Number(l.debit || 0);
      credit += Number(l.credit || 0);
    }
  }));
  return credit - debit;
}

/* رصيد ذمم عميل معيّن (مدين له = موجب) من واقع القيود المرحّلة فعلياً */
/* دالة عامة: رصيد أي طرف (عميل أو مورد) على حساب معيّن، موسوماً بحقل مرجعي (customerId/supplierId) */
function partyAccountBalance(entries, account, tagField, tagValue) {
  let debit = 0, credit = 0;
  entries.forEach((e) => e.lines.forEach((l) => {
    if (l.account === account && l[tagField] === tagValue) {
      debit += Number(l.debit || 0);
      credit += Number(l.credit || 0);
    }
  }));
  return { debit, credit };
}

function customerAccountBalance(entries, customerId) {
  const { debit, credit } = partyAccountBalance(entries, "ذمم مدينة", "customerId", customerId);
  return debit - credit;
}

function supplierAccountBalance(entries, supplierId) {
  const { debit, credit } = partyAccountBalance(entries, "ذمم دائنة - موردين", "supplierId", supplierId);
  return credit - debit;
}

/* إجمالي المبلغ المسدد من فاتورة معيّنة عبر كل سندات القبض المرتبطة بها */
function invoicePaidAmount(receipts, invoiceId) {
  return receipts.reduce((sum, r) => {
    const alloc = (r.allocations || []).find((a) => a.invoiceId === invoiceId);
    return sum + (alloc ? alloc.amount : 0);
  }, 0);
}

/* تحديد نوع الفاتورة وفق متطلبات هيئة الزكاة والضريبة والجمارك (فاتورة ضريبية قياسية للمنشآت، مبسّطة للأفراد) */
function invoiceTypeForCustomer(customer) {
  return customer && customer.customerType === "business" && customer.vatNumber ? "standard" : "simplified";
}

/* توليد حمولة رمز الاستجابة السريعة (QR) وفق معيار TLV المعتمد من هيئة الزكاة والضريبة والجمارك (المرحلة الأولى) */
function buildZatcaQrPayload(sellerName, sellerVat, isoTimestamp, invoiceTotal, vatTotal) {
  const encoder = new TextEncoder();
  const tlv = (tag, value) => {
    const bytes = encoder.encode(String(value || ""));
    return new Uint8Array([tag, bytes.length, ...bytes]);
  };
  const parts = [
    tlv(1, sellerName),
    tlv(2, sellerVat),
    tlv(3, isoTimestamp),
    tlv(4, invoiceTotal.toFixed(2)),
    tlv(5, vatTotal.toFixed(2)),
  ];
  const total = parts.reduce((s, p) => s + p.length, 0);
  const buf = new Uint8Array(total);
  let offset = 0;
  parts.forEach((p) => { buf.set(p, offset); offset += p.length; });
  let binary = "";
  buf.forEach((b) => { binary += String.fromCharCode(b); });
  return btoa(binary);
}

function nextDocNumber(list, prefix, field) {
  const n = list.length ? Math.max(...list.map((x) => Number((x[field] || "").split("-").pop()) || 0)) + 1 : 1;
  return `${prefix}-${String(n).padStart(5, "0")}`;
}

function entryTotal(entry) {
  return entry.lines.reduce((s, l) => s + Number(l.debit || 0), 0);
}

function filterEntries(entries, companyId) {
  return companyId === "all" ? entries : entries.filter((e) => e.company === companyId);
}

/* تجميع الأرصدة لكل حساب من كل الأسطر ضمن قيود شركة معيّنة */
function aggregateAccounts(entries, companyId) {
  const list = filterEntries(entries, companyId);
  const map = {};
  ACCOUNTS.forEach((a) => (map[a.name] = { debit: 0, credit: 0 }));
  list.forEach((e) => {
    e.lines.forEach((l) => {
      if (!map[l.account]) map[l.account] = { debit: 0, credit: 0 };
      map[l.account].debit += Number(l.debit || 0);
      map[l.account].credit += Number(l.credit || 0);
    });
  });
  return map;
}

/* عقرب قياس على طراز عداد محطة الوقود / إبرة البوصلة */
function Gauge({ label, value, max, unit, tone }) {
  const pct = Math.max(0, Math.min(1, value / max));
  const r = 54;
  const cx = 60, cy = 64;
  const startA = (-120 * Math.PI) / 180;
  const endA = (120 * Math.PI) / 180;
  const arcPoint = (a) => [cx + r * Math.sin(a), cy - r * Math.cos(a)];
  const [sx, sy] = arcPoint(startA);
  const [ex, ey] = arcPoint(endA);
  const [px, py] = arcPoint(startA + pct * (endA - startA));

  return (
    <div className="gauge-card">
      <svg viewBox="0 0 120 92" className="gauge-svg">
        <path d={`M ${sx} ${sy} A ${r} ${r} 0 1 1 ${ex} ${ey}`} className="gauge-track" />
        <path
          d={`M ${sx} ${sy} A ${r} ${r} 0 ${pct > 0.708 ? 1 : 0} 1 ${px} ${py}`}
          stroke={tone}
          className="gauge-fill"
        />
        <line x1={cx} y1={cy} x2={px} y2={py} stroke={tone} className="gauge-needle" />
        <circle cx={cx} cy={cy} r="3.4" fill={tone} />
      </svg>
      <div className="gauge-value" style={{ color: tone }}>
        {unit === "ر.س" ? fmt(value) : fmt2(value)} <span className="gauge-unit">{unit}</span>
      </div>
      <div className="gauge-label">{label}</div>
    </div>
  );
}

/* رسم دائري مصغّر (دونات) — لتوزيع نسب حالات المعاملات، بهوية بوصلة/إبرة متسقة مع باقي النظام */
function MiniDonut({ title, segments }) {
  const total = segments.reduce((s, x) => s + x.value, 0) || 1;
  const r = 42, cx = 50, cy = 50, circumference = 2 * Math.PI * r;
  let offsetAcc = 0;
  return (
    <div className="analytics-card">
      <div className="analytics-title">{title}</div>
      <div className="mini-donut-row">
        <svg viewBox="0 0 100 100" className="mini-donut-svg">
          <circle r={r} cx={cx} cy={cy} fill="none" stroke="rgba(16,32,46,0.06)" strokeWidth="14" />
          {segments.map((s, i) => {
            const frac = s.value / total;
            const dash = frac * circumference;
            const circle = (
              <circle
                key={i} r={r} cx={cx} cy={cy} fill="none" stroke={s.color} strokeWidth="14"
                strokeDasharray={`${dash} ${circumference - dash}`}
                strokeDashoffset={-offsetAcc}
                transform={`rotate(-90 ${cx} ${cy})`}
                strokeLinecap={segments.length > 1 ? "butt" : "round"}
              />
            );
            offsetAcc += dash;
            return circle;
          })}
          <text x={cx} y={cy + 5} textAnchor="middle" className="mini-donut-total">{total}</text>
        </svg>
        <div className="mini-legend">
          {segments.map((s, i) => (
            <div className="legend-item" key={i}>
              <span className="legend-dot" style={{ background: s.color }} />
              <span className="legend-label">{s.label}</span>
              <span className="legend-value">{s.value}</span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

/* رسم أعمدة مصغّر — لمقارنة قيم بين فئات (طريقة الدفع، الحالة...) */
function MiniBarChart({ title, bars, valueFormatter }) {
  const maxVal = Math.max(...bars.map((b) => b.value), 1);
  const fmtFn = valueFormatter || ((v) => fmt(v));
  return (
    <div className="analytics-card">
      <div className="analytics-title">{title}</div>
      <div className="mini-bar-chart">
        {bars.map((b, i) => (
          <div className="mini-bar-col" key={i}>
            <div className="mini-bar-value">{fmtFn(b.value)}</div>
            <div className="mini-bar-track"><div className="mini-bar-fill" style={{ height: `${(b.value / maxVal) * 100}%`, background: b.color }} /></div>
            <div className="mini-bar-label">{b.label}</div>
          </div>
        ))}
      </div>
    </div>
  );
}

/* ============ لوحة القيادة ============ */

function Dashboard({ entries, sales, employees, companyDocuments, companyId, setCompanyId }) {
  const filteredEntries = filterEntries(entries, companyId);
  const totalDebit = filteredEntries.reduce((s, e) => s + entryTotal(e), 0);
  const relevantStations = companyId === "all" ? STATIONS : STATIONS.filter((s) => s.company === companyId);
  const stationIds = new Set(relevantStations.map((s) => s.id));
  const filteredSales = sales.filter((s) => stationIds.has(s.stationId));
  const totalLiters = filteredSales.reduce((s, r) => s + r.liters, 0);
  const totalRevenue = filteredSales.reduce((s, r) => s + r.liters * r.pricePerLiter, 0);
  const avgPrice = totalLiters ? totalRevenue / totalLiters : 0;

  const expiringEmpDocs = collectExpiringEmployeeDocs(employees, companyId, 30);
  const expiringCompanyDocs = collectExpiringCompanyDocs(companyDocuments, companyId, 30);
  const totalAlerts = expiringEmpDocs.length + expiringCompanyDocs.length;

  return (
    <div>
      <div className="section-title">
        <span className="eyebrow">نظرة عامة</span>
        <h2>لوحة القيادة المالية</h2>
      </div>

      <div className="company-icon-row">
        {COMPANIES.map((c) => (
          <button
            key={c.id}
            className={"company-icon-card" + (companyId === c.id ? " active" : "")}
            style={{ borderColor: companyId === c.id ? c.brandColor : undefined }}
            onClick={() => setCompanyId(c.id)}
          >
            {c.logo ? (
              <img src={c.logo} alt={c.name} className="company-icon-logo" />
            ) : (
              <div className="company-icon-mark" style={{ background: c.brandColor }}>
                {c.short?.[0] || c.name?.[0]}
              </div>
            )}
            <span className="company-icon-label">{c.short}</span>
          </button>
        ))}
      </div>

      {totalAlerts > 0 && (
        <div className="alerts-panel">
          <div className="alerts-head">⚠ تنبيهات مستندات قاربت على الانتهاء أو انتهت ({totalAlerts})</div>
          <div className="alerts-grid">
            {expiringEmpDocs.map((r, i) => (
              <div key={"e" + i} className={"alert-chip" + (r.days < 0 ? " alert-expired" : "")}>
                <strong>{r.employee.name}</strong> — {r.doc.type}
                <span className="alert-days">{r.days < 0 ? `منتهٍ منذ ${Math.abs(r.days)} يوم` : `متبقٍ ${r.days} يوم`}</span>
              </div>
            ))}
            {expiringCompanyDocs.map((r, i) => (
              <div key={"c" + i} className={"alert-chip" + (r.days < 0 ? " alert-expired" : "")}>
                <strong>{COMPANIES.find((c) => c.id === r.doc.company)?.short}</strong> — {r.doc.docType}{r.doc.location ? ` (${costCenterName(r.doc.location)})` : ""}
                <span className="alert-days">{r.days < 0 ? `منتهٍ منذ ${Math.abs(r.days)} يوم` : `متبقٍ ${r.days} يوم`}</span>
              </div>
            ))}
          </div>
        </div>
      )}

      <div className="gauge-row">
        <Gauge label="حجم الحركة المحاسبية" value={totalDebit} max={600000} unit="ر.س" tone="#2F5D5A" />
        <Gauge label="مبيعات الوقود (لتر)" value={totalLiters} max={100000} unit="لتر" tone="#B98B4E" />
        <Gauge label="متوسط سعر اللتر" value={avgPrice} max={3} unit="ر.س" tone="#3E6B8A" />
        <Gauge label="عدد القيود المسجّلة" value={filteredEntries.length} max={20} unit="قيد" tone="#8A5A3E" />
      </div>
      <div className="two-col">
        <div className="panel">
          <h3>آخر القيود</h3>
          <ul className="mini-list">
            {filteredEntries.slice(-4).reverse().map((e) => (
              <li key={e.id}>
                <span className="mini-date">{e.date}</span>
                <span className="mini-memo">{e.memo}</span>
                <span className="mini-amount">{fmt(entryTotal(e))} ر.س</span>
              </li>
            ))}
            {filteredEntries.length === 0 && <li className="empty">لا توجد قيود لهذا الكيان بعد</li>}
          </ul>
        </div>
        <div className="panel">
          <h3>مبيعات المحطات الأخيرة</h3>
          <ul className="mini-list">
            {filteredSales.slice(-4).reverse().map((r) => {
              const st = STATIONS.find((s) => s.id === r.stationId);
              return (
                <li key={r.id}>
                  <span className="mini-date">{r.date}</span>
                  <span className="mini-memo">{st?.name}</span>
                  <span className="mini-amount">{fmt(r.liters * r.pricePerLiter)} ر.س</span>
                </li>
              );
            })}
            {filteredSales.length === 0 && <li className="empty">لا توجد مبيعات مسجّلة لهذا الكيان</li>}
          </ul>
        </div>
      </div>
    </div>
  );
}

