function downloadCsv(filename, rows) {
  const csv = rows.map((r) => r.map((c) => `"${String(c ?? "").replace(/"/g, '""')}"`).join(",")).join("\r\n");
  const blob = new Blob(["\uFEFF" + csv], { type: "text/csv;charset=utf-8;" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url; a.download = filename;
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

function ExcelImportPanel({ title, exampleRows, onImportRows }) {
  const [importMsg, setImportMsg] = useState("");

  const downloadTemplate = () => {
    const ws = XLSX.utils.json_to_sheet(exampleRows);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "نموذج");
    XLSX.writeFile(wb, `${title}.xlsx`);
  };

  const handleFile = (e) => {
    const file = e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (ev) => {
      try {
        const data = new Uint8Array(ev.target.result);
        const wb = XLSX.read(data, { type: "array" });
        const sheet = wb.Sheets[wb.SheetNames[0]];
        const rows = XLSX.utils.sheet_to_json(sheet, { defval: "" });
        setImportMsg(onImportRows(rows));
      } catch (err) {
        setImportMsg("تعذّرت قراءة الملف: " + err.message);
      }
    };
    reader.readAsArrayBuffer(file);
    e.target.value = "";
  };

  return (
    <div className="panel excel-import-panel">
      <h3>استيراد {title} من إكسل</h3>
      <div className="form-btn-group">
        <button className="btn-ghost" onClick={downloadTemplate}>تحميل نموذج إكسل فارغ</button>
        <label className="btn-primary file-upload-btn">
          رفع ملف إكسل
          <input type="file" accept=".xlsx,.xls" onChange={handleFile} style={{ display: "none" }} />
        </label>
      </div>
      {importMsg && <p className="note">{importMsg}</p>}
    </div>
  );
}

function TxIconBar({ onView, onPrint, onExcel, onEdit, onDelete, onPost, onUnpost, posted }) {
  return (
    <div className="tx-icon-bar">
      {onView && <button className="icon-btn" title="عرض" onClick={onView}><Icon.Eye /></button>}
      {onPrint && <button className="icon-btn" title="طباعة" onClick={onPrint}><Icon.Printer /></button>}
      {onExcel && <button className="icon-btn" title="تحميل Excel" onClick={onExcel}><Icon.Download /></button>}
      {onEdit && <button className="icon-btn" title="تعديل" onClick={onEdit} disabled={posted}><Icon.Edit /></button>}
      {onDelete && <button className="icon-btn icon-btn-danger" title="حذف" onClick={onDelete} disabled={posted}><Icon.Trash /></button>}
      {onPost && !posted && <button className="icon-btn" title="ترحيل" onClick={onPost}><Icon.Lock /></button>}
      {onUnpost && posted && <button className="icon-btn icon-btn-warn" title="فك الترحيل" onClick={onUnpost}><Icon.Unlock /></button>}
    </div>
  );
}

/* لوحة تأكيد بسيطة تطلب الرقم السري قبل فك ترحيل أي معاملة */
function UnpostConfirm({ onConfirm, onCancel, unlockPin }) {
  const [pin, setPin] = useState("");
  const [error, setError] = useState(false);
  const submit = () => {
    if (pin !== unlockPin) { setError(true); return; }
    onConfirm();
  };
  return (
    <div className="unpost-confirm-overlay">
      <div className="unpost-confirm-box">
        <h3>فك ترحيل المعاملة</h3>
        <p className="note">أدخل الرقم السري لتأكيد فك الترحيل. سيتم حذف القيد المحاسبي المرتبط بهذه المعاملة.</p>
        <input type="password" value={pin} onChange={(e) => { setPin(e.target.value); setError(false); }} placeholder="الرقم السري" />
        {error && <p className="balance-bad">رقم سري غير صحيح.</p>}
        <div className="form-btn-group">
          <button className="btn-ghost" onClick={onCancel}>إلغاء</button>
          <button className="btn-primary" onClick={submit}>تأكيد فك الترحيل</button>
        </div>
      </div>
    </div>
  );
}

function QrImage({ payload, size = 150 }) {
  const [src, setSrc] = useState(null);
  useEffect(() => {
    let cancelled = false;
    setSrc(null);
    if (payload) {
      QRCode.toDataURL(payload, { margin: 1, width: size }).then((url) => { if (!cancelled) setSrc(url); }).catch(() => setSrc(null));
    }
    return () => { cancelled = true; };
  }, [payload, size]);
  if (!src) return <div className="qr-loading">جارِ توليد رمز QR...</div>;
  return <img src={src} alt="QR Code" className="qr-image" width={size} height={size} />;
}

function printWithOrientation(landscape) {
  const id = "temp-orientation-style";
  let styleEl = document.getElementById(id);
  if (landscape) {
    if (!styleEl) { styleEl = document.createElement("style"); styleEl.id = id; document.body.appendChild(styleEl); }
    else { document.body.appendChild(styleEl); } // move to end so it wins the cascade over the component's own static @page rule
    styleEl.textContent = "@page { size: landscape; margin: 10mm; }";
  } else if (styleEl) {
    styleEl.remove();
  }
  window.print();
}

function PrintShell({ subtitle, refNode, children, onClose, onEdit, showSignatures = true, company, landscape = false }) {
  const accent = company?.brandColor || "#10202E";
  return createPortal(
    <div className="voucher-overlay">
      <div className="voucher-shell">
        <div className="voucher-print">
          <div className="voucher-head" style={{ borderBottomColor: accent }}>
            <div className="voucher-brand">
              {company?.logo ? (
                <img src={company.logo} alt={company.name} className="voucher-logo-img" />
              ) : (
                <div className="brand-mark voucher-mark" style={{ borderColor: accent }}>
                  <span className="brand-mark-needle" style={{ background: accent }} />
                </div>
              )}
              <div>
                <div className="voucher-brand-name">{company && company.id !== "all" ? company.name : "أثر المحاسبي"}</div>
                <div className="voucher-brand-sub">{subtitle}</div>
              </div>
            </div>
            <div className="voucher-ref">{refNode}</div>
          </div>

          {children}

          {showSignatures && (
            <div className="voucher-signatures">
              <div className="sig-box"><span>أعدّه</span><div className="sig-line" /></div>
              <div className="sig-box"><span>اعتمده</span><div className="sig-line" /></div>
              <div className="sig-box"><span>الختم</span><div className="sig-stamp">مكان الختم المعتمد</div></div>
            </div>
          )}
        </div>

        <div className="voucher-actions">
          {onEdit && <button className="btn-ghost" onClick={onEdit}>تعديل</button>}
          <button className="btn-ghost" onClick={() => printWithOrientation(landscape)}>طباعة</button>
          <button className="btn-primary" onClick={() => printWithOrientation(landscape)}>تحميل PDF</button>
          <button className="btn-ghost" onClick={onClose}>إغلاق</button>
        </div>
      </div>
    </div>,
    document.body
  );
}

function VoucherModal({ entry, onClose, onEdit }) {
  if (!entry) return null;
  const company = COMPANIES.find((c) => c.id === entry.company);
  const total = entryTotal(entry);

  return (
    <PrintShell
      subtitle="سند قيد محاسبي"
      refNode={
        <>
          <div>رقم القيد: <strong>{String(entry.id).padStart(5, "0")}</strong></div>
          <div>التاريخ: <strong>{entry.date}</strong></div>
        </>
      }
      onClose={onClose}
      onEdit={() => onEdit(entry)}
      company={COMPANIES.find((c) => c.id === entry.company)}
    >
      <div className="voucher-meta">
        <div><span>الشركة</span><strong>{company?.name}</strong></div>
        <div><span>البيان</span><strong>{entry.memo || "بدون بيان"}</strong></div>
      </div>

      <table className="ledger-table voucher-table">
        <thead>
          <tr><th>الحساب</th><th>مركز التكلفة</th><th>القسم</th><th>مدين</th><th>دائن</th></tr>
        </thead>
        <tbody>
          {entry.lines.map((l, i) => (
            <tr key={i}>
              <td>{l.account}</td>
              <td>{costCenterName(l.costCenter)}</td>
              <td>{l.department || "—"}</td>
              <td className="num">{l.debit ? fmt(l.debit) : "—"}</td>
              <td className="num">{l.credit ? fmt(l.credit) : "—"}</td>
            </tr>
          ))}
        </tbody>
        <tfoot>
          <tr><td className="foot-label" colSpan={3}>الإجمالي</td><td className="num strong">{fmt(total)}</td><td className="num strong">{fmt(total)}</td></tr>
        </tfoot>
      </table>
    </PrintShell>
  );
}

function JournalModule({ entries, setEntries, companyId }) {
  const blankHeader = () => ({ company: companyId === "all" ? "tesm" : companyId, date: "2026-07-20", memo: "" });
  const [header, setHeader] = useState(blankHeader());
  const [lines, setLines] = useState([emptyLine(), emptyLine()]);
  const [editingId, setEditingId] = useState(null);
  const [previewEntry, setPreviewEntry] = useState(null);
  const [searchText, setSearchText] = useState("");
  const [dateFrom, setDateFrom] = useState("");
  const [dateTo, setDateTo] = useState("");

  const list = filterEntries(entries, companyId);
  const costCenterOptions = COST_CENTERS.filter((c) => c.company === "all" || c.company === header.company);

  const totalDebit = lines.reduce((s, l) => s + Number(l.debit || 0), 0);
  const totalCredit = lines.reduce((s, l) => s + Number(l.credit || 0), 0);
  const diff = totalDebit - totalCredit;
  const canPost = lines.length >= 2 && totalDebit > 0 && diff === 0;

  const updateLine = (idx, field, value) => {
    setLines((prev) => prev.map((l, i) => (i === idx ? { ...l, [field]: value } : l)));
  };
  const addLine = () => setLines((prev) => [...prev, emptyLine()]);
  const removeLine = (idx) => setLines((prev) => (prev.length > 2 ? prev.filter((_, i) => i !== idx) : prev));

  const resetForm = () => {
    setEditingId(null);
    setHeader(blankHeader());
    setLines([emptyLine(), emptyLine()]);
  };

  const startEdit = (entry) => {
    setPreviewEntry(null);
    setEditingId(entry.id);
    setHeader({ company: entry.company, date: entry.date, memo: entry.memo });
    setLines(entry.lines.map((l) => ({ ...l, debit: l.debit || "", credit: l.credit || "" })));
  };

  const postEntry = () => {
    if (!canPost) return;
    const cleanLines = lines
      .filter((l) => Number(l.debit || 0) > 0 || Number(l.credit || 0) > 0)
      .map((l) => ({ account: l.account, costCenter: l.costCenter, department: l.department, debit: Number(l.debit || 0), credit: Number(l.credit || 0) }));

    if (editingId) {
      setEntries((prev) => prev.map((e) => (e.id === editingId ? { ...e, ...header, lines: cleanLines } : e)));
    } else {
      setEntries((prev) => [
        ...prev,
        { id: prev.length ? Math.max(...prev.map((e) => e.id)) + 1 : 1, ...header, lines: cleanLines },
      ]);
    }
    resetForm();
  };

  return (
    <div>
      <div className="section-title">
        <span className="eyebrow">دفتر اليومية</span>
        <h2>القيود المحاسبية</h2>
      </div>

      <div className="panel form-panel">
        {editingId && <div className="edit-banner">تعديل القيد رقم {String(editingId).padStart(5, "0")}</div>}
        <div className="form-grid header-grid">
          <label>
            الشركة
            <select value={header.company} onChange={(e) => setHeader({ ...header, company: e.target.value })}>
              {COMPANIES.filter((c) => c.id !== "all").map((c) => (
                <option key={c.id} value={c.id}>{c.name}</option>
              ))}
            </select>
          </label>
          <label>
            التاريخ
            <input type="date" value={header.date} onChange={(e) => setHeader({ ...header, date: e.target.value })} />
          </label>
          <label className="memo-field">
            بيان القيد
            <input type="text" value={header.memo} onChange={(e) => setHeader({ ...header, memo: e.target.value })} placeholder="وصف عام للقيد المركّب" />
          </label>
        </div>

        <div className="lines-table-wrap">
          <table className="lines-table">
            <thead>
              <tr>
                <th>الحساب</th>
                <th>مركز التكلفة</th>
                <th>القسم</th>
                <th>مدين</th>
                <th>دائن</th>
                <th></th>
              </tr>
            </thead>
            <tbody>
              {lines.map((l, idx) => (
                <tr key={idx}>
                  <td>
                    <select value={l.account} onChange={(e) => updateLine(idx, "account", e.target.value)}>
                      {ACCOUNTS.map((a) => <option key={a.name} value={a.name}>{a.name}</option>)}
                    </select>
                  </td>
                  <td>
                    <select value={l.costCenter} onChange={(e) => updateLine(idx, "costCenter", e.target.value)}>
                      <option value="">— بدون —</option>
                      {costCenterOptions.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}
                    </select>
                  </td>
                  <td>
                    <select value={l.department} onChange={(e) => updateLine(idx, "department", e.target.value)}>
                      {DEPARTMENTS.map((d) => <option key={d} value={d}>{d}</option>)}
                    </select>
                  </td>
                  <td>
                    <input type="number" className="amount-input" value={l.debit} onChange={(e) => updateLine(idx, "debit", e.target.value)} placeholder="0.00" />
                  </td>
                  <td>
                    <input type="number" className="amount-input" value={l.credit} onChange={(e) => updateLine(idx, "credit", e.target.value)} placeholder="0.00" />
                  </td>
                  <td>
                    <button className="btn-remove-line" onClick={() => removeLine(idx)} disabled={lines.length <= 2} title="حذف السطر">✕</button>
                  </td>
                </tr>
              ))}
            </tbody>
            <tfoot>
              <tr>
                <td className="foot-label" colSpan={3}>الإجمالي</td>
                <td className="num">{fmt2(totalDebit)}</td>
                <td className="num">{fmt2(totalCredit)}</td>
                <td></td>
              </tr>
            </tfoot>
          </table>
        </div>

        <div className="journal-actions">
          <button className="btn-ghost" onClick={addLine}>+ إضافة سطر</button>
          <div className="balance-status">
            {diff === 0 && totalDebit > 0 && <span className="balance-ok">✓ القيد متوازن — جاهز للترحيل</span>}
            {diff !== 0 && <span className="balance-bad">الفرق بين المدين والدائن: {fmt2(Math.abs(diff))} ر.س</span>}
            {diff === 0 && totalDebit === 0 && <span className="balance-hint">أدخل مبالغ القيد لبدء الترحيل</span>}
          </div>
          <div className="form-btn-group">
            {editingId && <button className="btn-ghost" onClick={resetForm}>إلغاء التعديل</button>}
            <button className="btn-primary" onClick={postEntry} disabled={!canPost}>{editingId ? "حفظ التعديلات" : "ترحيل القيد"}</button>
          </div>
        </div>
      </div>

      {(() => {
        const filtered = list.filter((e) => {
          if (searchText && !((e.memo || "").includes(searchText) || String(e.id).includes(searchText))) return false;
          if (dateFrom && e.date < dateFrom) return false;
          if (dateTo && e.date > dateTo) return false;
          return true;
        });
        const byCompany = {};
        list.forEach((e) => { byCompany[e.company] = (byCompany[e.company] || 0) + entryTotal(e); });
        const byMonth = {};
        list.forEach((e) => { const m = e.date.slice(0, 7); byMonth[m] = (byMonth[m] || 0) + entryTotal(e); });
        const months = Object.keys(byMonth).sort().slice(-5);
        const palette = ["#2F5D5A", "#B98B4E", "#3E6B8A", "#8A5A3E", "#6B4E8A"];

        return (
          <>
            {list.length > 0 && (
              <div className="analytics-row">
                {companyId === "all" ? (
                  <MiniDonut title="حجم القيود حسب الشركة" segments={Object.entries(byCompany).map(([cid, value], i) => ({ label: COMPANIES.find((c) => c.id === cid)?.short || cid, value, color: palette[i % palette.length] }))} />
                ) : (
                  <MiniDonut title="عدد القيود" segments={[{ label: "إجمالي القيود", value: list.length, color: "#2F5D5A" }]} />
                )}
                <MiniBarChart title="حجم الحركة آخر 5 أشهر" bars={months.map((m) => ({ label: monthLabel(m).split(" ")[0], value: byMonth[m], color: "#B98B4E" }))} />
              </div>
            )}

            <div className="panel form-panel">
              <div className="filter-bar">
                <input type="text" value={searchText} onChange={(e) => setSearchText(e.target.value)} placeholder="بحث بالبيان أو رقم القيد" />
                <input type="date" value={dateFrom} onChange={(e) => setDateFrom(e.target.value)} title="من تاريخ" />
                <input type="date" value={dateTo} onChange={(e) => setDateTo(e.target.value)} title="إلى تاريخ" />
              </div>
            </div>

            <div className="entries-feed">
              {filtered.slice().reverse().map((e) => (
                <div className="panel entry-card" key={e.id}>
                  <div className="entry-card-head">
                    <div>
                      <span className="entry-memo">{e.memo || "بدون بيان"}</span>
                      <span className="entry-meta">{e.date} · {COMPANIES.find((c) => c.id === e.company)?.short} · قيد رقم {String(e.id).padStart(5, "0")}</span>
                    </div>
                    <span className="entry-total">{fmt(entryTotal(e))} ر.س</span>
                  </div>
                  <table className="ledger-table entry-lines">
                    <thead>
                      <tr><th>الحساب</th><th>مركز التكلفة</th><th>القسم</th><th>مدين</th><th>دائن</th></tr>
                    </thead>
                    <tbody>
                      {e.lines.map((l, i) => (
                        <tr key={i}>
                          <td>{l.account}</td>
                          <td>{costCenterName(l.costCenter)}</td>
                          <td>{l.department || "—"}</td>
                          <td className="num">{l.debit ? fmt(l.debit) : "—"}</td>
                          <td className="num">{l.credit ? fmt(l.credit) : "—"}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                  <div className="entry-card-actions">
                    <TxIconBar
                      onView={() => setPreviewEntry(e)}
                      onPrint={() => { setPreviewEntry(e); setTimeout(() => printWithOrientation(false), 200); }}
                      onExcel={() => downloadCsv(`قيد_${e.id}.csv`, [["الحساب", "مركز التكلفة", "القسم", "مدين", "دائن"], ...e.lines.map((l) => [l.account, costCenterName(l.costCenter), l.department, l.debit, l.credit])])}
                      onEdit={() => startEdit(e)}
                      onDelete={() => { if (window.confirm("حذف هذا القيد نهائياً؟")) setEntries((prev) => prev.filter((x) => x.id !== e.id)); }}
                    />
                  </div>
                </div>
              ))}
              {filtered.length === 0 && <p className="empty">لا توجد قيود مطابقة لهذا البحث.</p>}
            </div>
          </>
        );
      })()}

      <ExcelImportPanel
        title="القيود اليومية"
        exampleRows={[{ "التاريخ": "2026-07-20", "البيان": "مثال: إيجار شهر يوليو", "حساب مدين": "مصروف إيجار", "مبلغ مدين": 5000, "حساب دائن": "البنك الأهلي - حساب تشغيلي", "مبلغ دائن": 5000 }]}
        onImportRows={(rows) => {
          if (companyId === "all") return "⚠ اختر شركة محددة من أيقونات لوحة القيادة أولاً لاستيراد القيود.";
          let count = 0, errCount = 0;
          const newOnes = [];
          rows.forEach((r) => {
            const date = r["التاريخ"], memo = r["البيان"] || "";
            const debitAcc = r["حساب مدين"], debitAmt = Number(r["مبلغ مدين"] || 0);
            const creditAcc = r["حساب دائن"], creditAmt = Number(r["مبلغ دائن"] || 0);
            if (!date || !debitAcc || !creditAcc || debitAmt <= 0 || Math.abs(debitAmt - creditAmt) > 0.01) { errCount++; return; }
            newOnes.push({ company: companyId, date: String(date), memo, lines: [{ account: debitAcc, debit: debitAmt, credit: 0 }, { account: creditAcc, debit: 0, credit: creditAmt }] });
            count++;
          });
          if (count > 0) {
            setEntries((prev) => {
              let nextId = prev.length ? Math.max(...prev.map((x) => x.id)) + 1 : 1;
              return [...prev, ...newOnes.map((e) => ({ id: nextId++, ...e }))];
            });
          }
          return `تم استيراد ${count} قيد بنجاح${errCount ? `، وتم تجاهل ${errCount} صف غير صالح (تأكد من تطابق مبلغ المدين والدائن)` : ""}.`;
        }}
      />

      <VoucherModal entry={previewEntry} onClose={() => setPreviewEntry(null)} onEdit={startEdit} />
    </div>
  );
}

/* ============ مبيعات المحطات ============ */

function StationsModule({ sales, setSales, companyId }) {
  const companyStations = companyId === "all" ? STATIONS : STATIONS.filter((s) => s.company === companyId);
  const [form, setForm] = useState({
    stationId: companyStations[0]?.id || STATIONS[0].id,
    date: "2026-07-20",
    liters: "",
    pricePerLiter: "2.18",
    shiftNote: "",
  });

  const stationIds = new Set(companyStations.map((s) => s.id));
  const list = sales.filter((s) => stationIds.has(s.stationId));

  const addSale = () => {
    if (!form.liters || Number(form.liters) <= 0) return;
    setSales((prev) => [
      ...prev,
      {
        id: prev.length ? Math.max(...prev.map((s) => s.id)) + 1 : 1,
        ...form,
        liters: Number(form.liters),
        pricePerLiter: Number(form.pricePerLiter),
      },
    ]);
    setForm((f) => ({ ...f, liters: "", shiftNote: "" }));
  };

  return (
    <div>
      <div className="section-title">
        <span className="eyebrow">تشغيل المحطات</span>
        <h2>متابعة مبيعات المحطات اليومية</h2>
      </div>

      {companyId !== "all" && companyStations.length === 0 ? (
        <div className="panel"><p className="empty">لا توجد محطات مرتبطة بهذا الكيان في هذا العرض التجريبي.</p></div>
      ) : (
        <>
          <div className="panel form-panel">
            <div className="form-grid">
              <label>
                المحطة
                <select value={form.stationId} onChange={(e) => setForm({ ...form, stationId: e.target.value })}>
                  {companyStations.map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}
                </select>
              </label>
              <label>
                التاريخ
                <input type="date" value={form.date} onChange={(e) => setForm({ ...form, date: e.target.value })} />
              </label>
              <label>
                الكمية (لتر)
                <input type="number" value={form.liters} onChange={(e) => setForm({ ...form, liters: e.target.value })} placeholder="0" />
              </label>
              <label>
                سعر اللتر
                <input type="number" step="0.01" value={form.pricePerLiter} onChange={(e) => setForm({ ...form, pricePerLiter: e.target.value })} />
              </label>
              <label className="memo-field">
                ملاحظة الوردية
                <input type="text" value={form.shiftNote} onChange={(e) => setForm({ ...form, shiftNote: e.target.value })} placeholder="مثال: وردية صباحية" />
              </label>
            </div>
            <button className="btn-primary" onClick={addSale}>تسجيل المبيعات</button>
          </div>

          <div className="panel">
            <table className="ledger-table">
              <thead>
                <tr><th>التاريخ</th><th>المحطة</th><th>لتر</th><th>سعر اللتر</th><th>الإجمالي</th><th>الوردية</th></tr>
              </thead>
              <tbody>
                {list.slice().reverse().map((r) => {
                  const st = STATIONS.find((s) => s.id === r.stationId);
                  return (
                    <tr key={r.id}>
                      <td>{r.date}</td>
                      <td>{st?.name}</td>
                      <td className="num">{fmt(r.liters)}</td>
                      <td className="num">{fmt2(r.pricePerLiter)}</td>
                      <td className="num">{fmt(r.liters * r.pricePerLiter)}</td>
                      <td>{r.shiftNote}</td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
            {list.length === 0 && <p className="empty">لا توجد مبيعات مسجّلة بعد.</p>}
          </div>
        </>
      )}
    </div>
  );
}

/* ============ الزكاة والضريبة ============ */

function ZakatModule({ entries, sales, companyId }) {
  const acc = aggregateAccounts(entries, companyId);
  const outputVatFromEntries = (acc["المبيعات - وقود"]?.credit || 0) + (acc["المبيعات - زيوت وخدمات"]?.credit || 0);
  const relevantStations = companyId === "all" ? STATIONS : STATIONS.filter((s) => s.company === companyId);
  const stationIds = new Set(relevantStations.map((s) => s.id));
  const stationRevenue = sales.filter((s) => stationIds.has(s.stationId)).reduce((s, r) => s + r.liters * r.pricePerLiter, 0);
  const salesBase = outputVatFromEntries + stationRevenue;
  const outputVat = (acc["ضريبة القيمة المضافة - مخرجات"]?.credit || 0) + stationRevenue * 0.15;
  const inputVat = (acc["ضريبة القيمة المضافة - مدخلات"]?.debit || 0);
  const netVat = outputVat - inputVat;
  const zakatBase = salesBase * 0.15; // نسبة تقديرية توضيحية فقط

  return (
    <div>
      <div className="section-title">
        <span className="eyebrow">الامتثال الضريبي</span>
        <h2>الزكاة وضريبة القيمة المضافة</h2>
      </div>
      <p className="note">
        الأرقام هنا تقديرية لأغراض العرض التجريبي فقط، وتُبنى من نفس بيانات القيود والمبيعات المسجّلة أعلاه —
        وليست بديلاً عن ربط فعلي ببوابة زاتكا.
      </p>
      <div className="gauge-row">
        <Gauge label="إجمالي المبيعات الخاضعة" value={salesBase} max={800000} unit="ر.س" tone="#2F5D5A" />
        <Gauge label="ضريبة المخرجات" value={outputVat} max={120000} unit="ر.س" tone="#A8432B" />
        <Gauge label="ضريبة المدخلات" value={inputVat} max={30000} unit="ر.س" tone="#3E6B8A" />
        <Gauge label="صافي الضريبة المستحقة" value={Math.max(netVat, 0)} max={100000} unit="ر.س" tone="#B98B4E" />
      </div>
      <div className="panel">
        <h3>وعاء الزكاة التقديري</h3>
        <table className="ledger-table">
          <tbody>
            <tr><td>إجمالي المبيعات الخاضعة</td><td className="num">{fmt(salesBase)} ر.س</td></tr>
            <tr><td>نسبة تقديرية للوعاء الزكوي</td><td className="num">15٪ (تجريبية)</td></tr>
            <tr><td className="strong">الوعاء الزكوي التقديري</td><td className="num strong">{fmt(zakatBase)} ر.س</td></tr>
          </tbody>
        </table>
      </div>
    </div>
  );
}

/* ============ التقارير المالية الرئيسية ============ */

const REPORT_TABS = [
  { id: "trial", label: "ميزان المراجعة" },
  { id: "income", label: "قائمة الدخل" },
  { id: "balance", label: "المركز المالي" },
];

function TrialBalanceReport({ acc }) {
  const rows = ACCOUNTS.map((a) => {
    const d = acc[a.name]?.debit || 0;
    const c = acc[a.name]?.credit || 0;
    return { name: a.name, type: a.type, debit: d, credit: c, net: d - c };
  });
  const totalDebit = rows.reduce((s, r) => s + r.debit, 0);
  const totalCredit = rows.reduce((s, r) => s + r.credit, 0);

  return (
    <div className="panel">
      <h3>ميزان المراجعة</h3>
      <table className="ledger-table">
        <thead>
          <tr><th>الحساب</th><th>التصنيف</th><th>مدين</th><th>دائن</th><th>الرصيد</th></tr>
        </thead>
        <tbody>
          {rows.map((r) => (
            <tr key={r.name}>
              <td>{r.name}</td>
              <td className="type-tag">{TYPE_LABEL[r.type]}</td>
              <td className="num">{r.debit ? fmt(r.debit) : "—"}</td>
              <td className="num">{r.credit ? fmt(r.credit) : "—"}</td>
              <td className="num">{r.net >= 0 ? `${fmt(r.net)} مدين` : `${fmt(Math.abs(r.net))} دائن`}</td>
            </tr>
          ))}
        </tbody>
        <tfoot>
          <tr>
            <td className="foot-label">الإجمالي</td><td></td>
            <td className="num strong">{fmt(totalDebit)}</td>
            <td className="num strong">{fmt(totalCredit)}</td>
            <td className={"num " + (totalDebit === totalCredit ? "balance-ok" : "balance-bad")}>
              {totalDebit === totalCredit ? "متوازن ✓" : "غير متوازن"}
            </td>
          </tr>
        </tfoot>
      </table>
    </div>
  );
}

function IncomeStatementReport({ acc }) {
  const revenueRows = ACCOUNTS.filter((a) => a.type === "revenue").map((a) => ({
    name: a.name, amount: (acc[a.name]?.credit || 0) - (acc[a.name]?.debit || 0),
  }));
  const expenseRows = ACCOUNTS.filter((a) => a.type === "expense").map((a) => ({
    name: a.name, amount: (acc[a.name]?.debit || 0) - (acc[a.name]?.credit || 0),
  }));
  const totalRevenue = revenueRows.reduce((s, r) => s + r.amount, 0);
  const totalExpense = expenseRows.reduce((s, r) => s + r.amount, 0);
  const netIncome = totalRevenue - totalExpense;

  return (
    <>
      <div className="gauge-row gauge-row-3">
        <Gauge label="إجمالي الإيرادات" value={totalRevenue} max={800000} unit="ر.س" tone="#2F5D5A" />
        <Gauge label="إجمالي المصروفات" value={totalExpense} max={200000} unit="ر.س" tone="#A8432B" />
        <Gauge label="صافي الربح" value={Math.max(netIncome, 0)} max={600000} unit="ر.س" tone="#B98B4E" />
      </div>
      <div className="panel">
        <h3>قائمة الدخل</h3>
        <table className="ledger-table">
          <tbody>
            <tr><td className="strong section-row" colSpan={2}>الإيرادات</td></tr>
            {revenueRows.map((r) => (
              <tr key={r.name}><td className="indent">{r.name}</td><td className="num">{fmt(r.amount)}</td></tr>
            ))}
            <tr><td className="strong">إجمالي الإيرادات</td><td className="num strong">{fmt(totalRevenue)}</td></tr>

            <tr><td className="strong section-row" colSpan={2}>المصروفات</td></tr>
            {expenseRows.map((r) => (
              <tr key={r.name}><td className="indent">{r.name}</td><td className="num">{fmt(r.amount)}</td></tr>
            ))}
            <tr><td className="strong">إجمالي المصروفات</td><td className="num strong">{fmt(totalExpense)}</td></tr>

            <tr className="net-row"><td className="strong">صافي الربح</td><td className="num strong">{fmt(netIncome)}</td></tr>
          </tbody>
        </table>
      </div>
    </>
  );
}

function BalanceSheetReport({ acc, netIncome }) {
  const assetRows = ACCOUNTS.filter((a) => a.type === "asset").map((a) => ({
    name: a.name, amount: (acc[a.name]?.debit || 0) - (acc[a.name]?.credit || 0),
  }));
  const liabilityRows = ACCOUNTS.filter((a) => a.type === "liability").map((a) => ({
    name: a.name, amount: (acc[a.name]?.credit || 0) - (acc[a.name]?.debit || 0),
  }));
  const equityBase = ACCOUNTS.filter((a) => a.type === "equity").map((a) => ({
    name: a.name, amount: (acc[a.name]?.credit || 0) - (acc[a.name]?.debit || 0),
  }));

  const totalAssets = assetRows.reduce((s, r) => s + r.amount, 0);
  const totalLiabilities = liabilityRows.reduce((s, r) => s + r.amount, 0);
  const totalEquityBase = equityBase.reduce((s, r) => s + r.amount, 0);
  const totalEquity = totalEquityBase + netIncome;
  const balanced = Math.abs(totalAssets - (totalLiabilities + totalEquity)) < 1;

  return (
    <>
      <div className="gauge-row gauge-row-3">
        <Gauge label="إجمالي الأصول" value={totalAssets} max={800000} unit="ر.س" tone="#2F5D5A" />
        <Gauge label="إجمالي الالتزامات" value={totalLiabilities} max={200000} unit="ر.س" tone="#A8432B" />
        <Gauge label="حقوق الملكية" value={totalEquity} max={600000} unit="ر.س" tone="#B98B4E" />
      </div>
      <div className="two-col">
        <div className="panel">
          <h3>الأصول</h3>
          <table className="ledger-table">
            <tbody>
              {assetRows.map((r) => (
                <tr key={r.name}><td>{r.name}</td><td className="num">{fmt(r.amount)}</td></tr>
              ))}
              <tr className="net-row"><td className="strong">إجمالي الأصول</td><td className="num strong">{fmt(totalAssets)}</td></tr>
            </tbody>
          </table>
        </div>
        <div className="panel">
          <h3>الالتزامات وحقوق الملكية</h3>
          <table className="ledger-table">
            <tbody>
              <tr><td className="strong section-row" colSpan={2}>الالتزامات</td></tr>
              {liabilityRows.map((r) => (
                <tr key={r.name}><td className="indent">{r.name}</td><td className="num">{fmt(r.amount)}</td></tr>
              ))}
              <tr><td className="strong">إجمالي الالتزامات</td><td className="num strong">{fmt(totalLiabilities)}</td></tr>

              <tr><td className="strong section-row" colSpan={2}>حقوق الملكية</td></tr>
              {equityBase.map((r) => (
                <tr key={r.name}><td className="indent">{r.name}</td><td className="num">{fmt(r.amount)}</td></tr>
              ))}
              <tr><td className="indent">صافي ربح الفترة</td><td className="num">{fmt(netIncome)}</td></tr>
              <tr><td className="strong">إجمالي حقوق الملكية</td><td className="num strong">{fmt(totalEquity)}</td></tr>

              <tr className="net-row">
                <td className="strong">إجمالي الالتزامات وحقوق الملكية</td>
                <td className={"num strong " + (balanced ? "balance-ok" : "balance-bad")}>
                  {fmt(totalLiabilities + totalEquity)} {balanced ? "✓" : "⚠"}
                </td>
              </tr>
            </tbody>
          </table>
        </div>
      </div>
    </>
  );
}

function ReportsModule({ entries, companyId, tab, setTab }) {
  const acc = useMemo(() => aggregateAccounts(entries, companyId), [entries, companyId]);

  const totalRevenue = ACCOUNTS.filter((a) => a.type === "revenue")
    .reduce((s, a) => s + ((acc[a.name]?.credit || 0) - (acc[a.name]?.debit || 0)), 0);
  const totalExpense = ACCOUNTS.filter((a) => a.type === "expense")
    .reduce((s, a) => s + ((acc[a.name]?.debit || 0) - (acc[a.name]?.credit || 0)), 0);
  const netIncome = totalRevenue - totalExpense;

  return (
    <div>
      <div className="section-title">
        <span className="eyebrow">الإفصاح المالي</span>
        <h2>التقارير المالية الرئيسية</h2>
      </div>
      <div className="report-tabs">
        {REPORT_TABS.map((t) => (
          <button key={t.id} className={"report-tab" + (tab === t.id ? " active" : "")} onClick={() => setTab(t.id)}>
            {t.label}
          </button>
        ))}
      </div>
      {tab === "trial" && <TrialBalanceReport acc={acc} />}
      {tab === "income" && <IncomeStatementReport acc={acc} />}
      {tab === "balance" && <BalanceSheetReport acc={acc} netIncome={netIncome} />}
    </div>
  );
}

