/* ============ المبيعات: عروض الأسعار ============ */

function QuotationsModule({ customers, quotes, setQuotes, invoices, setInvoices, entries, setEntries, companyId }) {
  const companyCustomers = companyId === "all" ? customers : customers.filter((c) => c.company === companyId);
  const [customerId, setCustomerId] = useState(companyCustomers[0]?.id || "");
  const [date, setDate] = useState("2026-07-20");
  const [validUntil, setValidUntil] = useState("2026-08-19");
  const [lines, setLines] = useState([emptyInvoiceLine()]);
  const [previewQuote, setPreviewQuote] = useState(null);
  const [editingId, setEditingId] = useState(null);

  const list = quotes.filter((q) => companyCustomers.some((c) => c.id === q.customerId));
  const customer = customers.find((c) => c.id === customerId);
  const computedLines = lines.map((l) => ({ ...l, ...computeInvoiceLine(l) }));
  const subtotal = computedLines.reduce((s, l) => s + l.subtotal, 0);
  const vatTotal = computedLines.reduce((s, l) => s + l.vat, 0);
  const grandTotal = subtotal + vatTotal;

  const updateLine = (idx, field, value) => setLines((prev) => prev.map((l, i) => (i === idx ? { ...l, [field]: value } : l)));
  const addLine = () => setLines((prev) => [...prev, emptyInvoiceLine()]);
  const removeLine = (idx) => setLines((prev) => (prev.length > 1 ? prev.filter((_, i) => i !== idx) : prev));
  const resetForm = () => { setEditingId(null); setLines([emptyInvoiceLine()]); };

  const saveQuote = () => {
    if (!customer || grandTotal <= 0) return;
    const cleanLines = computedLines.map(({ account, description, quantity, unitPrice, discountPct, priceIncludesVat, subtotal: st, vat, total }) => ({ account, description, quantity: Number(quantity), unitPrice: Number(unitPrice), discountPct: Number(discountPct), priceIncludesVat, subtotal: st, vat, total }));
    if (editingId) {
      setQuotes((prev) => prev.map((q) => (q.id === editingId ? { ...q, customerId: customer.id, date, validUntil, lines: cleanLines, subtotal, vatTotal, grandTotal } : q)));
    } else {
      const quoteNumber = nextDocNumber(quotes, "QUO", "quoteNumber");
      setQuotes((prev) => [...prev, { id: prev.length ? Math.max(...prev.map((q) => q.id)) + 1 : 1, quoteNumber, company: customer.company, customerId: customer.id, date, validUntil, lines: cleanLines, subtotal, vatTotal, grandTotal, status: "draft", convertedInvoiceId: null }]);
    }
    resetForm();
  };

  const startEdit = (q) => {
    if (q.status === "converted") return;
    setEditingId(q.id); setCustomerId(q.customerId); setDate(q.date); setValidUntil(q.validUntil);
    setLines(q.lines.map((l) => ({ ...l }))); setPreviewQuote(null);
  };
  const deleteQuote = (q) => {
    if (q.status === "converted") return;
    if (!window.confirm(`حذف عرض السعر ${q.quoteNumber}؟`)) return;
    setQuotes((prev) => prev.filter((x) => x.id !== q.id));
  };

  const convertToInvoice = (q) => {
    if (q.status === "converted") return;
    const c = customers.find((x) => x.id === q.customerId);
    if (!c) return;
    const invoiceNumber = nextDocNumber(invoices, "INV", "invoiceNumber");
    const byAccount = {};
    q.lines.forEach((l) => { byAccount[l.account] = (byAccount[l.account] || 0) + l.subtotal; });
    const jLines = Object.entries(byAccount).map(([account, amount]) => ({ account, costCenter: "", department: "المبيعات والتسويق", debit: 0, credit: amount, customerId: c.id }));
    jLines.push({ account: "ضريبة القيمة المضافة - مخرجات", costCenter: "", department: "المالية والحسابات", debit: 0, credit: q.vatTotal, customerId: c.id });
    jLines.push({ account: "ذمم مدينة", costCenter: "", department: "المالية والحسابات", debit: q.grandTotal, credit: 0, customerId: c.id });
    const entryId = entries.length ? Math.max(...entries.map((e) => e.id)) + 1 : 1;
    const today = "2026-07-20";
    setEntries((prev) => [...prev, { id: entryId, company: c.company, date: today, memo: `فاتورة مبيعات ${invoiceNumber} — ${c.name} (من عرض سعر ${q.quoteNumber})`, lines: jLines }]);
    const invType = invoiceTypeForCustomer(c);
    const qrPayload = buildZatcaQrPayload(COMPANIES.find((x) => x.id === c.company)?.name || "", COMPANIES.find((x) => x.id === c.company)?.vatNumber || "", `${today}T12:00:00`, q.grandTotal, q.vatTotal);
    const newInvoiceId = invoices.length ? Math.max(...invoices.map((i) => i.id)) + 1 : 1;
    setInvoices((prev) => [...prev, { id: newInvoiceId, invoiceNumber, company: c.company, customerId: c.id, date: today, invoiceType: invType, lines: q.lines, subtotal: q.subtotal, vatTotal: q.vatTotal, grandTotal: q.grandTotal, journalEntryId: entryId, qrPayload, status: "posted" }]);
    setQuotes((prev) => prev.map((x) => (x.id === q.id ? { ...x, status: "converted", convertedInvoiceId: newInvoiceId } : x)));
  };

  const exportQuoteCsv = (q) => {
    const c = customers.find((x) => x.id === q.customerId);
    const rows = [["الوصف", "الكمية", "سعر الوحدة", "خصم %", "قبل الضريبة", "الضريبة", "الإجمالي"]];
    q.lines.forEach((l) => rows.push([l.description || l.account, l.quantity, l.unitPrice, l.discountPct, l.subtotal.toFixed(2), l.vat.toFixed(2), l.total.toFixed(2)]));
    downloadCsv(`${q.quoteNumber}_${c?.name || ""}.csv`, rows);
  };

  return (
    <div>
      <div className="panel form-panel">
        {editingId && <div className="edit-banner">تعديل عرض السعر {quotes.find((q) => q.id === editingId)?.quoteNumber}</div>}
        <div className="form-grid header-grid">
          <label>العميل<select value={customerId} onChange={(e) => setCustomerId(Number(e.target.value))}>{companyCustomers.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}</select></label>
          <label>تاريخ العرض<input type="date" value={date} onChange={(e) => setDate(e.target.value)} /></label>
          <label>صالح حتى<input type="date" value={validUntil} onChange={(e) => setValidUntil(e.target.value)} /></label>
        </div>
        <div className="lines-table-wrap">
          <table className="lines-table">
            <thead><tr><th>الحساب</th><th>الوصف</th><th>الكمية</th><th>سعر الوحدة</th><th>شامل الضريبة؟</th><th>خصم %</th><th>الإجمالي</th><th></th></tr></thead>
            <tbody>
              {computedLines.map((l, idx) => (
                <tr key={idx}>
                  <td><select value={l.account} onChange={(e) => updateLine(idx, "account", e.target.value)}>{SALES_REVENUE_ACCOUNTS.map((a) => <option key={a} value={a}>{a}</option>)}</select></td>
                  <td><input type="text" value={l.description} onChange={(e) => updateLine(idx, "description", e.target.value)} /></td>
                  <td><input type="number" className="amount-input" value={l.quantity} onChange={(e) => updateLine(idx, "quantity", e.target.value)} /></td>
                  <td><input type="number" className="amount-input" value={l.unitPrice} onChange={(e) => updateLine(idx, "unitPrice", e.target.value)} /></td>
                  <td style={{ textAlign: "center" }}><input type="checkbox" checked={l.priceIncludesVat} onChange={(e) => updateLine(idx, "priceIncludesVat", e.target.checked)} /></td>
                  <td><input type="number" className="amount-input" value={l.discountPct} onChange={(e) => updateLine(idx, "discountPct", e.target.value)} /></td>
                  <td className="num">{fmt2(l.total)}</td>
                  <td><button className="btn-remove-line" onClick={() => removeLine(idx)} disabled={lines.length <= 1}>✕</button></td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        <div className="preview-box">
          <div className="preview-row"><span>قبل الضريبة</span><strong>{fmt(subtotal)} ر.س</strong></div>
          <div className="preview-row"><span>الضريبة</span><strong>{fmt(vatTotal)} ر.س</strong></div>
          <div className="preview-row net-row"><span>الإجمالي</span><strong>{fmt(grandTotal)} ر.س</strong></div>
        </div>
        <div className="journal-actions">
          <button className="btn-ghost" onClick={addLine}>+ إضافة سطر</button>
          <div className="form-btn-group">
            {editingId && <button className="btn-ghost" onClick={resetForm}>إلغاء</button>}
            <button className="btn-primary" onClick={saveQuote} disabled={!customer || grandTotal <= 0}>{editingId ? "حفظ التعديلات" : "حفظ عرض السعر"}</button>
          </div>
        </div>
      </div>

      <div className="entries-feed">
        {list.slice().reverse().map((q) => {
          const c = customers.find((x) => x.id === q.customerId);
          return (
            <div className="panel entry-card" key={q.id}>
              <div className="entry-card-head">
                <div>
                  <span className="entry-memo">{q.quoteNumber} — {c?.name}</span>
                  <span className="entry-meta">{q.date} · صالح حتى {q.validUntil} · {q.status === "converted" ? "تم التحويل لفاتورة" : "قيد المراجعة"}</span>
                </div>
                <span className="entry-total">{fmt(q.grandTotal)} ر.س</span>
              </div>
              <div className="entry-card-actions">
                {q.status !== "converted" && <button className="btn-primary" onClick={() => convertToInvoice(q)}>تحويل لفاتورة</button>}
              </div>
              <TxIconBar
                onView={() => setPreviewQuote(q)}
                onPrint={() => { setPreviewQuote(q); setTimeout(() => printWithOrientation(false), 200); }}
                onExcel={() => exportQuoteCsv(q)}
                onEdit={q.status !== "converted" ? () => startEdit(q) : undefined}
                onDelete={q.status !== "converted" ? () => deleteQuote(q) : undefined}
              />
            </div>
          );
        })}
        {list.length === 0 && <p className="empty">لا توجد عروض أسعار مسجّلة بعد.</p>}
      </div>

      {previewQuote && (() => {
        const c = customers.find((x) => x.id === previewQuote.customerId);
        const company = COMPANIES.find((x) => x.id === previewQuote.company);
        return (
          <PrintShell subtitle="عرض سعر" company={company} refNode={<><div>رقم العرض: <strong>{previewQuote.quoteNumber}</strong></div><div>صالح حتى: <strong>{previewQuote.validUntil}</strong></div></>} onClose={() => setPreviewQuote(null)}>
            <div className="voucher-meta"><div><span>العميل</span><strong>{c?.name}</strong></div><div><span>تاريخ العرض</span><strong>{previewQuote.date}</strong></div></div>
            <table className="ledger-table voucher-table">
              <thead><tr><th>الوصف</th><th>الكمية</th><th>سعر الوحدة</th><th>قبل الضريبة</th><th>الضريبة</th><th>الإجمالي</th></tr></thead>
              <tbody>{previewQuote.lines.map((l, i) => (<tr key={i}><td>{l.description || l.account}</td><td className="num">{l.quantity}</td><td className="num">{fmt2(l.unitPrice)}</td><td className="num">{fmt(l.subtotal)}</td><td className="num">{fmt(l.vat)}</td><td className="num strong">{fmt(l.total)}</td></tr>))}</tbody>
              <tfoot><tr><td className="foot-label" colSpan={3}>الإجمالي</td><td className="num strong">{fmt(previewQuote.subtotal)}</td><td className="num strong">{fmt(previewQuote.vatTotal)}</td><td className="num strong">{fmt(previewQuote.grandTotal)}</td></tr></tfoot>
            </table>
          </PrintShell>
        );
      })()}
    </div>
  );
}

/* ============ المبيعات: سندات القبض ============ */

function ReceiptsModule({ customers, invoices, receipts, setReceipts, entries, setEntries, companyId, unlockPin }) {
  const companyCustomers = companyId === "all" ? customers : customers.filter((c) => c.company === companyId);
  const [customerId, setCustomerId] = useState(companyCustomers[0]?.id || "");
  const [date, setDate] = useState("2026-07-20");
  const [method, setMethod] = useState("cash");
  const [allocations, setAllocations] = useState({});
  const [previewReceipt, setPreviewReceipt] = useState(null);
  const [unpostTarget, setUnpostTarget] = useState(null);

  const customerInvoices = invoices.filter((i) => i.customerId === customerId).map((i) => ({ ...i, paid: invoicePaidAmount(receipts, i.id) })).filter((i) => i.paid < i.grandTotal - 0.5);
  const list = receipts.filter((r) => companyCustomers.some((c) => c.id === r.customerId));

  const totalAllocated = Object.values(allocations).reduce((s, v) => s + Number(v || 0), 0);

  const setAlloc = (invId, value) => setAllocations((prev) => ({ ...prev, [invId]: value }));
  const autoAllocate = () => {
    const na = {};
    // FIFO by date
    const sorted = customerInvoices.slice().sort((a, b) => new Date(a.date) - new Date(b.date));
    let remaining = sorted.reduce((s, i) => s + (i.grandTotal - i.paid), 0);
    sorted.forEach((i) => {
      const due = i.grandTotal - i.paid;
      const alloc = Math.min(due, remaining);
      if (alloc > 0) na[i.id] = alloc.toFixed(2);
      remaining -= alloc;
    });
    setAllocations(na);
  };

  const saveReceipt = () => {
    const customer = customers.find((c) => c.id === customerId);
    if (!customer || totalAllocated <= 0) return;
    const receiptNumber = nextDocNumber(receipts, "REC", "receiptNumber");
    const creditAccount = method === "cash" ? "النقدية بالصندوق" : "البنك الأهلي - حساب تشغيلي";
    const jLines = [
      { account: creditAccount, costCenter: "", department: "المالية والحسابات", debit: totalAllocated, credit: 0, customerId: customer.id },
      { account: "ذمم مدينة", costCenter: "", department: "المالية والحسابات", debit: 0, credit: totalAllocated, customerId: customer.id },
    ];
    const entryId = entries.length ? Math.max(...entries.map((e) => e.id)) + 1 : 1;
    setEntries((prev) => [...prev, { id: entryId, company: customer.company, date, memo: `سند قبض ${receiptNumber} — ${customer.name}`, lines: jLines }]);

    const allocList = Object.entries(allocations).filter(([, v]) => Number(v) > 0).map(([invoiceId, v]) => ({ invoiceId: Number(invoiceId), amount: Number(v) }));
    setReceipts((prev) => [...prev, {
      id: prev.length ? Math.max(...prev.map((r) => r.id)) + 1 : 1, receiptNumber, company: customer.company, customerId: customer.id,
      date, method, totalAmount: totalAllocated, allocations: allocList, journalEntryId: entryId, status: "posted",
    }]);
    setAllocations({});
  };

  const deleteReceipt = (r) => {
    if (r.status === "posted") return;
    if (!window.confirm(`حذف سند القبض ${r.receiptNumber}؟`)) return;
    setReceipts((prev) => prev.filter((x) => x.id !== r.id));
  };
  const unpostReceipt = (r) => {
    setEntries((prev) => prev.filter((e) => e.id !== r.journalEntryId));
    setReceipts((prev) => prev.map((x) => (x.id === r.id ? { ...x, status: "draft", journalEntryId: null } : x)));
    setUnpostTarget(null);
  };
  const repostReceipt = (r) => {
    const customer = customers.find((c) => c.id === r.customerId);
    const creditAccount = r.method === "cash" ? "النقدية بالصندوق" : "البنك الأهلي - حساب تشغيلي";
    const jLines = [
      { account: creditAccount, costCenter: "", department: "المالية والحسابات", debit: r.totalAmount, credit: 0, customerId: r.customerId },
      { account: "ذمم مدينة", costCenter: "", department: "المالية والحسابات", debit: 0, credit: r.totalAmount, customerId: r.customerId },
    ];
    const entryId = entries.length ? Math.max(...entries.map((e) => e.id)) + 1 : 1;
    setEntries((prev) => [...prev, { id: entryId, company: r.company, date: r.date, memo: `سند قبض ${r.receiptNumber} — ${customer?.name}`, lines: jLines }]);
    setReceipts((prev) => prev.map((x) => (x.id === r.id ? { ...x, status: "posted", journalEntryId: entryId } : x)));
  };
  const exportReceiptCsv = (r) => {
    const c = customers.find((x) => x.id === r.customerId);
    const rows = [["الفاتورة", "المبلغ المخصص"]];
    r.allocations.forEach((a) => { const inv = invoices.find((i) => i.id === a.invoiceId); rows.push([inv?.invoiceNumber || a.invoiceId, a.amount.toFixed(2)]); });
    downloadCsv(`${r.receiptNumber}_${c?.name || ""}.csv`, rows);
  };

  return (
    <div>
      <div className="panel form-panel">
        <div className="form-grid header-grid">
          <label>العميل<select value={customerId} onChange={(e) => { setCustomerId(Number(e.target.value)); setAllocations({}); }}>{companyCustomers.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}</select></label>
          <label>تاريخ السند<input type="date" value={date} onChange={(e) => setDate(e.target.value)} /></label>
          <label>طريقة التحصيل<select value={method} onChange={(e) => setMethod(e.target.value)}><option value="cash">كاش</option><option value="bank">بنك</option></select></label>
        </div>

        <h3 className="sub-head">الفواتير المستحقة على هذا العميل</h3>
        <div className="lines-table-wrap">
          <table className="lines-table">
            <thead><tr><th>الفاتورة</th><th>التاريخ</th><th>الإجمالي</th><th>المسدد</th><th>المتبقي</th><th>المبلغ المخصص الآن</th></tr></thead>
            <tbody>
              {customerInvoices.map((inv) => {
                const due = inv.grandTotal - inv.paid;
                return (
                  <tr key={inv.id}>
                    <td>{inv.invoiceNumber}</td><td>{inv.date}</td>
                    <td className="num">{fmt(inv.grandTotal)}</td><td className="num">{fmt(inv.paid)}</td><td className="num strong">{fmt(due)}</td>
                    <td><input type="number" className="amount-input" value={allocations[inv.id] || ""} onChange={(e) => setAlloc(inv.id, e.target.value)} placeholder="0.00" /></td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
        {customerInvoices.length === 0 && <p className="empty">لا توجد فواتير مستحقة على هذا العميل.</p>}

        <div className="journal-actions">
          <button className="btn-ghost" onClick={autoAllocate}>توزيع تلقائي (الأقدم أولاً)</button>
          <div className="preview-box" style={{ margin: 0 }}>
            <div className="preview-row net-row"><span>إجمالي السند</span><strong>{fmt(totalAllocated)} ر.س</strong></div>
          </div>
          <button className="btn-primary" onClick={saveReceipt} disabled={totalAllocated <= 0}>حفظ وترحيل سند القبض</button>
        </div>
      </div>

      <div className="entries-feed">
        {list.slice().reverse().map((r) => {
          const c = customers.find((x) => x.id === r.customerId);
          const posted = r.status !== "draft";
          return (
            <div className="panel entry-card" key={r.id}>
              <div className="entry-card-head">
                <div>
                  <span className="entry-memo">{r.receiptNumber} — {c?.name}</span>
                  <span className="entry-meta">{r.date} · {r.method === "cash" ? "كاش" : "بنك"}{!posted && " · مسودة"}</span>
                </div>
                <span className="entry-total">{fmt(r.totalAmount)} ر.س</span>
              </div>
              <TxIconBar
                onView={() => setPreviewReceipt(r)}
                onPrint={() => { setPreviewReceipt(r); setTimeout(() => printWithOrientation(false), 200); }}
                onExcel={() => exportReceiptCsv(r)}
                onDelete={!posted ? () => deleteReceipt(r) : undefined}
                onPost={!posted ? () => repostReceipt(r) : undefined}
                onUnpost={() => setUnpostTarget(r)}
                posted={posted}
              />
            </div>
          );
        })}
        {list.length === 0 && <p className="empty">لا توجد سندات قبض مسجّلة بعد.</p>}
      </div>

      {unpostTarget && <UnpostConfirm unlockPin={unlockPin} onCancel={() => setUnpostTarget(null)} onConfirm={() => unpostReceipt(unpostTarget)} />}

      {previewReceipt && (() => {
        const c = customers.find((x) => x.id === previewReceipt.customerId);
        const company = COMPANIES.find((x) => x.id === previewReceipt.company);
        return (
          <PrintShell subtitle="سند قبض" company={company} refNode={<><div>رقم السند: <strong>{previewReceipt.receiptNumber}</strong></div><div>التاريخ: <strong>{previewReceipt.date}</strong></div></>} onClose={() => setPreviewReceipt(null)}>
            <div className="voucher-meta">
              <div><span>العميل</span><strong>{c?.name}</strong></div>
              <div><span>طريقة التحصيل</span><strong>{previewReceipt.method === "cash" ? "كاش" : "بنك"}</strong></div>
            </div>
            <table className="ledger-table voucher-table">
              <thead><tr><th>الفاتورة</th><th>المبلغ المخصص</th></tr></thead>
              <tbody>
                {previewReceipt.allocations.map((a, i) => {
                  const inv = invoices.find((x) => x.id === a.invoiceId);
                  return <tr key={i}><td>{inv?.invoiceNumber || "—"}</td><td className="num">{fmt(a.amount)}</td></tr>;
                })}
              </tbody>
              <tfoot><tr><td className="foot-label">الإجمالي</td><td className="num strong">{fmt(previewReceipt.totalAmount)}</td></tr></tfoot>
            </table>
          </PrintShell>
        );
      })()}
    </div>
  );
}

const SALES_TABS = [
  { id: "customers", label: "العملاء" },
  { id: "quotes", label: "عروض الأسعار" },
  { id: "invoices", label: "فواتير المبيعات" },
  { id: "returns", label: "مردودات المبيعات" },
  { id: "receipts", label: "سندات القبض" },
  { id: "stations", label: "مبيعات المحطات" },
  { id: "reports", label: "التقارير" },
];

function SalesModule({ customers, setCustomers, invoices, setInvoices, returns, setReturns, quotes, setQuotes, receipts, setReceipts, sales, setSales, entries, setEntries, companyId, tab, setTab, unlockPin }) {
  return (
    <div>
      <div className="section-title">
        <span className="eyebrow">التجارة والمبيعات</span>
        <h2>المبيعات</h2>
      </div>
      <div className="report-tabs">
        {SALES_TABS.map((t) => (
          <button key={t.id} className={"report-tab" + (tab === t.id ? " active" : "")} onClick={() => setTab(t.id)}>{t.label}</button>
        ))}
      </div>
      {tab === "customers" && <CustomerDirectory customers={customers} setCustomers={setCustomers} entries={entries} companyId={companyId} />}
      {tab === "quotes" && <QuotationsModule customers={customers} quotes={quotes} setQuotes={setQuotes} invoices={invoices} setInvoices={setInvoices} entries={entries} setEntries={setEntries} companyId={companyId} />}
      {tab === "invoices" && <SalesInvoiceModule customers={customers} invoices={invoices} setInvoices={setInvoices} receipts={receipts} entries={entries} setEntries={setEntries} companyId={companyId} unlockPin={unlockPin} />}
      {tab === "returns" && <SalesReturnsModule customers={customers} invoices={invoices} returns={returns} setReturns={setReturns} entries={entries} setEntries={setEntries} companyId={companyId} />}
      {tab === "receipts" && <ReceiptsModule customers={customers} invoices={invoices} receipts={receipts} setReceipts={setReceipts} entries={entries} setEntries={setEntries} companyId={companyId} unlockPin={unlockPin} />}
      {tab === "stations" && <StationsModule sales={sales} setSales={setSales} companyId={companyId} />}
      {tab === "reports" && <SalesReportsModule customers={customers} invoices={invoices} returns={returns} entries={entries} companyId={companyId} />}
    </div>
  );
}

/* ============ المشتريات: الموردون ============ */

function SupplierDirectory({ suppliers, setSuppliers, entries, companyId }) {
  const [form, setForm] = useState(emptySupplierForm(companyId));
  const [statementSupplier, setStatementSupplier] = useState(null);
  const list = companyId === "all" ? suppliers : suppliers.filter((s) => s.company === companyId);

  const addSupplier = () => {
    if (!form.name) return;
    setSuppliers((prev) => [...prev, { id: prev.length ? Math.max(...prev.map((s) => s.id)) + 1 : 1, ...form }]);
    setForm(emptySupplierForm(companyId));
  };

  return (
    <div>
      <div className="panel form-panel">
        <div className="form-grid">
          <label>اسم المورد<input type="text" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} /></label>
          <label>الشركة (جهة التعامل)
            <select value={form.company} onChange={(e) => setForm({ ...form, company: e.target.value })}>
              {COMPANIES.filter((c) => c.id !== "all").map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}
            </select>
          </label>
          <label>الرقم الضريبي<input type="text" maxLength={15} value={form.vatNumber} onChange={(e) => setForm({ ...form, vatNumber: e.target.value.replace(/\D/g, "") })} placeholder="3xxxxxxxxxxxxx3" /></label>
          <label>رقم السجل التجاري<input type="text" value={form.crNumber} onChange={(e) => setForm({ ...form, crNumber: e.target.value })} /></label>
          <label>الجوال<input type="text" value={form.phone} onChange={(e) => setForm({ ...form, phone: e.target.value })} /></label>
          <label>البريد الإلكتروني<input type="email" value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} /></label>
          <label>المدينة<input type="text" value={form.city} onChange={(e) => setForm({ ...form, city: e.target.value })} /></label>
          <label>شروط الدفع
            <select value={form.paymentTerms} onChange={(e) => setForm({ ...form, paymentTerms: e.target.value })}>
              {PAYMENT_TERMS.map((t) => <option key={t}>{t}</option>)}
            </select>
          </label>
        </div>
        <button className="btn-primary" onClick={addSupplier}>حفظ بيانات المورد</button>
      </div>

      <div className="hr-grid">
        {list.map((s) => {
          const balance = supplierAccountBalance(entries, s.id);
          return (
            <div className="panel emp-card" key={s.id}>
              <div className="emp-card-head">
                <div><div className="emp-name">{s.name}</div><div className="emp-role">{s.city || "—"}</div></div>
                <span className="status-badge">{s.paymentTerms}</span>
              </div>
              <div className="emp-meta-grid">
                <div><span>الرقم الضريبي</span><strong>{s.vatNumber || "—"}</strong></div>
                <div><span>السجل التجاري</span><strong>{s.crNumber || "—"}</strong></div>
                <div><span>الجوال</span><strong>{s.phone || "—"}</strong></div>
                <div><span>المستحق له</span><strong className={balance > 0 ? "balance-bad" : ""}>{fmt(balance)} ر.س</strong></div>
              </div>
              <div className="entry-card-actions">
                <button className="btn-ghost" onClick={() => setStatementSupplier(s)}>كشف حساب</button>
              </div>
            </div>
          );
        })}
        {list.length === 0 && <p className="empty">لا يوجد موردون مسجّلون لهذا الكيان بعد.</p>}
      </div>

      {statementSupplier && (() => {
        const rows = supplierLedgerRows(entries, statementSupplier.id);
        const company = COMPANIES.find((c) => c.id === statementSupplier.company);
        return (
          <PrintShell subtitle="كشف حساب مورد" company={company} refNode={<div>تاريخ الكشف: <strong>2026-07-20</strong></div>} onClose={() => setStatementSupplier(null)}>
            <div className="voucher-meta">
              <div><span>اسم المورد</span><strong>{statementSupplier.name}</strong></div>
              <div><span>الرقم الضريبي</span><strong>{statementSupplier.vatNumber || "—"}</strong></div>
            </div>
            <table className="ledger-table voucher-table">
              <thead><tr><th>التاريخ</th><th>البيان</th><th>مدين</th><th>دائن</th><th>الرصيد</th></tr></thead>
              <tbody>
                {rows.map((r, i) => (
                  <tr key={i}>
                    <td>{r.date}</td><td>{r.memo}</td>
                    <td className="num">{r.debit ? fmt(r.debit) : "—"}</td>
                    <td className="num">{r.credit ? fmt(r.credit) : "—"}</td>
                    <td className="num strong">{fmt(-r.balance)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
            {rows.length === 0 && <p className="empty">لا توجد حركات مسجّلة على هذا المورد.</p>}
          </PrintShell>
        );
      })()}
    </div>
  );
}

/* ============ المشتريات: فواتير المشتريات ============ */

function PurchaseInvoiceModule({ suppliers, invoices, setInvoices, entries, setEntries, companyId, unlockPin }) {
  const companySuppliers = companyId === "all" ? suppliers : suppliers.filter((s) => s.company === companyId);
  const [supplierId, setSupplierId] = useState(companySuppliers[0]?.id || "");
  const [date, setDate] = useState("2026-07-20");
  const [lines, setLines] = useState([{ account: PURCHASE_LINE_ACCOUNTS[0], description: "", quantity: 1, unitPrice: "", discountPct: 0 }]);
  const [previewInvoice, setPreviewInvoice] = useState(null);
  const [editingId, setEditingId] = useState(null);
  const [unpostTarget, setUnpostTarget] = useState(null);
  const [searchText, setSearchText] = useState("");
  const [statusFilter, setStatusFilter] = useState("all");

  const list = invoices.filter((inv) => companySuppliers.some((s) => s.id === inv.supplierId));
  const supplier = suppliers.find((s) => s.id === supplierId);
  const computedLines = lines.map((l) => ({ ...l, ...computeInvoiceLine(l) }));
  const subtotal = computedLines.reduce((s, l) => s + l.subtotal, 0);
  const vatTotal = computedLines.reduce((s, l) => s + l.vat, 0);
  const grandTotal = subtotal + vatTotal;

  const updateLine = (idx, field, value) => setLines((prev) => prev.map((l, i) => (i === idx ? { ...l, [field]: value } : l)));
  const addLine = () => setLines((prev) => [...prev, { account: PURCHASE_LINE_ACCOUNTS[0], description: "", quantity: 1, unitPrice: "", discountPct: 0 }]);
  const removeLine = (idx) => setLines((prev) => (prev.length > 1 ? prev.filter((_, i) => i !== idx) : prev));
  const resetForm = () => { setEditingId(null); setLines([{ account: PURCHASE_LINE_ACCOUNTS[0], description: "", quantity: 1, unitPrice: "", discountPct: 0 }]); };

  const buildJLines = (supplier, computedLines, vatTotal, grandTotal) => {
    const byAccount = {};
    computedLines.forEach((l) => { byAccount[l.account] = (byAccount[l.account] || 0) + l.subtotal; });
    const jLines = Object.entries(byAccount).map(([account, amount]) => ({ account, costCenter: "", department: "المشتريات", debit: amount, credit: 0, supplierId: supplier.id }));
    jLines.push({ account: "ضريبة القيمة المضافة - مدخلات", costCenter: "", department: "المالية والحسابات", debit: vatTotal, credit: 0, supplierId: supplier.id });
    jLines.push({ account: "ذمم دائنة - موردين", costCenter: "", department: "المالية والحسابات", debit: 0, credit: grandTotal, supplierId: supplier.id });
    return jLines;
  };

  const saveInvoice = () => {
    if (!supplier || grandTotal <= 0) return;
    const invoiceNumber = editingId ? invoices.find((i) => i.id === editingId).invoiceNumber : nextDocNumber(invoices, "PINV", "invoiceNumber");
    const jLines = buildJLines(supplier, computedLines, vatTotal, grandTotal);
    const entryId = entries.length ? Math.max(...entries.map((e) => e.id)) + 1 : 1;
    setEntries((prev) => [...prev, { id: entryId, company: supplier.company, date, memo: `فاتورة مشتريات ${invoiceNumber} — ${supplier.name}`, lines: jLines }]);
    const cleanLines = computedLines.map(({ account, description, quantity, unitPrice, discountPct, subtotal: st, vat, total }) => ({ account, description, quantity: Number(quantity), unitPrice: Number(unitPrice), discountPct: Number(discountPct), subtotal: st, vat, total }));

    if (editingId) {
      setInvoices((prev) => prev.map((i) => (i.id === editingId ? { ...i, supplierId: supplier.id, date, lines: cleanLines, subtotal, vatTotal, grandTotal, journalEntryId: entryId, status: "posted" } : i)));
    } else {
      setInvoices((prev) => [...prev, { id: prev.length ? Math.max(...prev.map((i) => i.id)) + 1 : 1, invoiceNumber, company: supplier.company, supplierId: supplier.id, date, lines: cleanLines, subtotal, vatTotal, grandTotal, journalEntryId: entryId, status: "posted" }]);
    }
    resetForm();
  };

  const startEdit = (inv) => {
    if (inv.status === "posted") return;
    setEditingId(inv.id); setSupplierId(inv.supplierId); setDate(inv.date);
    setLines(inv.lines.map((l) => ({ ...l }))); setPreviewInvoice(null);
  };
  const deleteInvoice = (inv) => {
    if (inv.status === "posted") return;
    if (!window.confirm(`حذف الفاتورة ${inv.invoiceNumber}؟`)) return;
    setInvoices((prev) => prev.filter((i) => i.id !== inv.id));
  };
  const unpostInvoice = (inv) => {
    setEntries((prev) => prev.filter((e) => e.id !== inv.journalEntryId));
    setInvoices((prev) => prev.map((i) => (i.id === inv.id ? { ...i, status: "draft", journalEntryId: null } : i)));
    setUnpostTarget(null);
  };
  const repostInvoice = (inv) => {
    const s = suppliers.find((x) => x.id === inv.supplierId);
    if (!s) return;
    const jLines = buildJLines(s, inv.lines, inv.vatTotal, inv.grandTotal);
    const entryId = entries.length ? Math.max(...entries.map((e) => e.id)) + 1 : 1;
    setEntries((prev) => [...prev, { id: entryId, company: s.company, date: inv.date, memo: `فاتورة مشتريات ${inv.invoiceNumber} — ${s.name}`, lines: jLines }]);
    setInvoices((prev) => prev.map((i) => (i.id === inv.id ? { ...i, status: "posted", journalEntryId: entryId } : i)));
  };
  const exportInvoiceCsv = (inv) => {
    const s = suppliers.find((x) => x.id === inv.supplierId);
    const rows = [["الوصف", "الكمية", "سعر الوحدة", "خصم %", "قبل الضريبة", "الضريبة", "الإجمالي"]];
    inv.lines.forEach((l) => rows.push([l.description || l.account, l.quantity, l.unitPrice, l.discountPct, l.subtotal.toFixed(2), l.vat.toFixed(2), l.total.toFixed(2)]));
    downloadCsv(`${inv.invoiceNumber}_${s?.name || ""}.csv`, rows);
  };

  return (
    <div>
      <div className="panel form-panel">
        {editingId && <div className="edit-banner">تعديل الفاتورة {invoices.find((i) => i.id === editingId)?.invoiceNumber}</div>}
        <div className="form-grid header-grid">
          <label>المورد
            <select value={supplierId} onChange={(e) => setSupplierId(Number(e.target.value))}>
              {companySuppliers.map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}
            </select>
          </label>
          <label>تاريخ الفاتورة<input type="date" value={date} onChange={(e) => setDate(e.target.value)} /></label>
        </div>
        {companySuppliers.length === 0 && <p className="empty">لا يوجد موردون مسجّلون لهذا الكيان — أضف مورداً أولاً.</p>}

        <div className="lines-table-wrap">
          <table className="lines-table">
            <thead><tr><th>الحساب</th><th>الوصف</th><th>الكمية</th><th>سعر الوحدة</th><th>خصم %</th><th>الإجمالي شامل الضريبة</th><th></th></tr></thead>
            <tbody>
              {computedLines.map((l, idx) => (
                <tr key={idx}>
                  <td><select value={l.account} onChange={(e) => updateLine(idx, "account", e.target.value)}>{PURCHASE_LINE_ACCOUNTS.map((a) => <option key={a} value={a}>{a}</option>)}</select></td>
                  <td><input type="text" value={l.description} onChange={(e) => updateLine(idx, "description", e.target.value)} placeholder="وصف الصنف/الخدمة" /></td>
                  <td><input type="number" className="amount-input" value={l.quantity} onChange={(e) => updateLine(idx, "quantity", e.target.value)} /></td>
                  <td><input type="number" className="amount-input" value={l.unitPrice} onChange={(e) => updateLine(idx, "unitPrice", e.target.value)} placeholder="0.00" /></td>
                  <td><input type="number" className="amount-input" value={l.discountPct} onChange={(e) => updateLine(idx, "discountPct", e.target.value)} /></td>
                  <td className="num">{fmt2(l.total)}</td>
                  <td><button className="btn-remove-line" onClick={() => removeLine(idx)} disabled={lines.length <= 1}>✕</button></td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        <div className="preview-box">
          <div className="preview-row"><span>قبل الضريبة</span><strong>{fmt(subtotal)} ر.س</strong></div>
          <div className="preview-row"><span>ضريبة القيمة المضافة (15٪)</span><strong>{fmt(vatTotal)} ر.س</strong></div>
          <div className="preview-row net-row"><span>الإجمالي شامل الضريبة</span><strong>{fmt(grandTotal)} ر.س</strong></div>
        </div>

        <div className="journal-actions">
          <button className="btn-ghost" onClick={addLine}>+ إضافة سطر</button>
          <div className="form-btn-group">
            {editingId && <button className="btn-ghost" onClick={resetForm}>إلغاء التعديل</button>}
            <button className="btn-primary" onClick={saveInvoice} disabled={!supplier || grandTotal <= 0}>{editingId ? "حفظ التعديلات وإعادة الترحيل" : "حفظ وترحيل الفاتورة"}</button>
          </div>
        </div>
      </div>

      {(() => {
        const filtered = list.filter((inv) => {
          const s = suppliers.find((x) => x.id === inv.supplierId);
          if (searchText && !(inv.invoiceNumber.includes(searchText) || (s?.name || "").includes(searchText))) return false;
          if (statusFilter !== "all" && (inv.status || "posted") !== statusFilter) return false;
          return true;
        });
        const postedCount = list.filter((i) => (i.status || "posted") !== "draft").length;
        const draftCount = list.length - postedCount;
        const byMonth = {};
        list.forEach((i) => { const m = i.date.slice(0, 7); byMonth[m] = (byMonth[m] || 0) + i.grandTotal; });
        const months = Object.keys(byMonth).sort().slice(-5);

        return (
          <>
            <div className="analytics-row">
              <MiniDonut
                title="توزيع فواتير المشتريات حسب الترحيل"
                segments={[
                  { label: "مرحّلة", value: postedCount, color: "#2F5D5A" },
                  { label: "مسودة", value: draftCount, color: "#B98B4E" },
                ]}
              />
              <MiniBarChart
                title="إجمالي المشتريات آخر 5 أشهر"
                bars={months.map((m) => ({ label: monthLabel(m).split(" ")[0], value: byMonth[m], color: "#8A5A3E" }))}
              />
            </div>

            <div className="panel">
              <div className="filter-bar">
                <input type="text" value={searchText} onChange={(e) => setSearchText(e.target.value)} placeholder="بحث برقم الفاتورة أو اسم المورد" />
                <select value={statusFilter} onChange={(e) => setStatusFilter(e.target.value)}>
                  <option value="all">كل حالات الترحيل</option>
                  <option value="posted">مرحّلة</option>
                  <option value="draft">مسودة</option>
                </select>
              </div>
              <div className="invoices-table-wrap">
                <table className="invoices-table">
                  <thead><tr><th>الفاتورة</th><th>المورد</th><th>التاريخ</th><th>الإجمالي</th><th>الترحيل</th><th>الإجراءات</th></tr></thead>
                  <tbody>
                    {filtered.slice().reverse().map((inv) => {
                      const s = suppliers.find((x) => x.id === inv.supplierId);
                      const posted = inv.status !== "draft";
                      return (
                        <tr key={inv.id}>
                          <td>{inv.invoiceNumber}</td><td>{s?.name}</td><td>{inv.date}</td>
                          <td className="num strong">{fmt(inv.grandTotal)}</td>
                          <td><span className={"status-pill " + (posted ? "pill-posted" : "pill-draft")}>{posted ? "مرحّلة" : "مسودة"}</span></td>
                          <td>
                            <TxIconBar
                              onView={() => setPreviewInvoice(inv)}
                              onPrint={() => { setPreviewInvoice(inv); setTimeout(() => printWithOrientation(false), 200); }}
                              onExcel={() => exportInvoiceCsv(inv)}
                              onEdit={!posted ? () => startEdit(inv) : undefined}
                              onDelete={!posted ? () => deleteInvoice(inv) : undefined}
                              onPost={!posted ? () => repostInvoice(inv) : undefined}
                              onUnpost={() => setUnpostTarget(inv)}
                              posted={posted}
                            />
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
                {filtered.length === 0 && <p className="empty">لا توجد فواتير مطابقة.</p>}
              </div>
            </div>
          </>
        );
      })()}

      {unpostTarget && <UnpostConfirm unlockPin={unlockPin} onCancel={() => setUnpostTarget(null)} onConfirm={() => unpostInvoice(unpostTarget)} />}

      <ExcelImportPanel
        title="فواتير المشتريات"
        exampleRows={[{ "رقم مرجعي": "REF1", "المورد": "اسم المورد بالضبط كما هو مسجّل", "التاريخ": "2026-07-20", "الحساب": PURCHASE_LINE_ACCOUNTS[0], "الوصف": "وصف الصنف", "الكمية": 1, "سعر الوحدة": 100, "خصم %": 0 }]}
        onImportRows={(rows) => {
          const groups = {};
          rows.forEach((r) => {
            const ref = r["رقم مرجعي"] || "بدون رقم";
            groups[ref] = groups[ref] || [];
            groups[ref].push(r);
          });
          let created = 0, skipped = 0;
          Object.entries(groups).forEach(([ref, rrows]) => {
            const supplierName = rrows[0]["المورد"];
            const sup = suppliers.find((s) => s.name === supplierName);
            if (!sup) { skipped += rrows.length; return; }
            const lns = rrows.map((r) => computeInvoiceLine({ quantity: Number(r["الكمية"] || 0), unitPrice: Number(r["سعر الوحدة"] || 0), discountPct: Number(r["خصم %"] || 0) }));
            const cLines = rrows.map((r, idx) => ({ account: r["الحساب"] || PURCHASE_LINE_ACCOUNTS[0], description: r["الوصف"] || "", quantity: Number(r["الكمية"] || 0), unitPrice: Number(r["سعر الوحدة"] || 0), discountPct: Number(r["خصم %"] || 0), ...lns[idx] }));
            const subtotal = cLines.reduce((s, l) => s + l.subtotal, 0);
            const vatT = cLines.reduce((s, l) => s + l.vat, 0);
            const grand = subtotal + vatT;
            const invoiceNumber = nextDocNumber(invoices, "PINV", "invoiceNumber");
            const jLines = buildJLines(sup, cLines, vatT, grand);
            const entryId = entries.length ? Math.max(...entries.map((e) => e.id)) + 1 : 1;
            setEntries((prev) => [...prev, { id: entryId, company: sup.company, date: String(rrows[0]["التاريخ"]), memo: `فاتورة مشتريات ${invoiceNumber} — ${sup.name} (استيراد)`, lines: jLines }]);
            setInvoices((prev) => [...prev, { id: prev.length ? Math.max(...prev.map((i) => i.id)) + 1 : 1, invoiceNumber, company: sup.company, supplierId: sup.id, date: String(rrows[0]["التاريخ"]), lines: cLines, subtotal, vatTotal: vatT, grandTotal: grand, journalEntryId: entryId, status: "posted" }]);
            created++;
          });
          return `تم إنشاء ${created} فاتورة${skipped ? `، وتجاهل ${skipped} صف (مورد غير موجود بنفس الاسم بالضبط)` : ""}.`;
        }}
      />

      {previewInvoice && (() => {
        const s = suppliers.find((x) => x.id === previewInvoice.supplierId);
        const company = COMPANIES.find((x) => x.id === previewInvoice.company);
        return (
          <PrintShell subtitle="فاتورة مشتريات" company={company} refNode={<><div>رقم الفاتورة: <strong>{previewInvoice.invoiceNumber}</strong></div><div>التاريخ: <strong>{previewInvoice.date}</strong></div></>} onClose={() => setPreviewInvoice(null)}>
            <div className="voucher-meta">
              <div><span>المورد</span><strong>{s?.name}</strong></div>
              <div><span>الرقم الضريبي للمورد</span><strong>{s?.vatNumber || "—"}</strong></div>
            </div>
            <table className="ledger-table voucher-table">
              <thead><tr><th>الوصف</th><th>الكمية</th><th>سعر الوحدة</th><th>قبل الضريبة</th><th>الضريبة</th><th>الإجمالي</th></tr></thead>
              <tbody>
                {previewInvoice.lines.map((l, i) => (
                  <tr key={i}><td>{l.description || l.account}</td><td className="num">{l.quantity}</td><td className="num">{fmt2(l.unitPrice)}</td><td className="num">{fmt(l.subtotal)}</td><td className="num">{fmt(l.vat)}</td><td className="num strong">{fmt(l.total)}</td></tr>
                ))}
              </tbody>
              <tfoot><tr><td className="foot-label" colSpan={3}>الإجمالي</td><td className="num strong">{fmt(previewInvoice.subtotal)}</td><td className="num strong">{fmt(previewInvoice.vatTotal)}</td><td className="num strong">{fmt(previewInvoice.grandTotal)}</td></tr></tfoot>
            </table>
          </PrintShell>
        );
      })()}
    </div>
  );
}

/* ============ المشتريات: مردودات المشتريات ============ */

function PurchaseReturnsModule({ suppliers, invoices, returns, setReturns, entries, setEntries, companyId }) {
  const companySuppliers = companyId === "all" ? suppliers : suppliers.filter((s) => s.company === companyId);
  const [supplierId, setSupplierId] = useState(companySuppliers[0]?.id || "");
  const [date, setDate] = useState("2026-07-20");
  const [reason, setReason] = useState("");
  const [lines, setLines] = useState([{ account: PURCHASE_LINE_ACCOUNTS[0], description: "", quantity: 1, unitPrice: "", discountPct: 0 }]);
  const [previewReturn, setPreviewReturn] = useState(null);

  const supplier = suppliers.find((s) => s.id === supplierId);
  const list = returns.filter((r) => companySuppliers.some((s) => s.id === r.supplierId));
  const computedLines = lines.map((l) => ({ ...l, ...computeInvoiceLine(l) }));
  const subtotal = computedLines.reduce((s, l) => s + l.subtotal, 0);
  const vatTotal = computedLines.reduce((s, l) => s + l.vat, 0);
  const grandTotal = subtotal + vatTotal;

  const updateLine = (idx, field, value) => setLines((prev) => prev.map((l, i) => (i === idx ? { ...l, [field]: value } : l)));
  const addLine = () => setLines((prev) => [...prev, { account: PURCHASE_LINE_ACCOUNTS[0], description: "", quantity: 1, unitPrice: "", discountPct: 0 }]);
  const removeLine = (idx) => setLines((prev) => (prev.length > 1 ? prev.filter((_, i) => i !== idx) : prev));

  const saveReturn = () => {
    if (!supplier || grandTotal <= 0) return;
    const returnNumber = nextDocNumber(returns, "PRET", "returnNumber");
    const byAccount = {};
    computedLines.forEach((l) => { byAccount[l.account] = (byAccount[l.account] || 0) + l.subtotal; });
    const jLines = Object.entries(byAccount).map(([account, amount]) => ({
      account, costCenter: "", department: "المشتريات", debit: 0, credit: amount, supplierId: supplier.id,
    }));
    jLines.push({ account: "ضريبة القيمة المضافة - مدخلات", costCenter: "", department: "المالية والحسابات", debit: 0, credit: vatTotal, supplierId: supplier.id });
    jLines.push({ account: "ذمم دائنة - موردين", costCenter: "", department: "المالية والحسابات", debit: grandTotal, credit: 0, supplierId: supplier.id });

    const entryId = entries.length ? Math.max(...entries.map((e) => e.id)) + 1 : 1;
    setEntries((prev) => [...prev, { id: entryId, company: supplier.company, date, memo: `مردود مشتريات ${returnNumber} — ${supplier.name}`, lines: jLines }]);

    setReturns((prev) => [
      ...prev,
      {
        id: prev.length ? Math.max(...prev.map((r) => r.id)) + 1 : 1,
        returnNumber, company: supplier.company, supplierId: supplier.id, date, reason,
        lines: computedLines.map(({ account, description, quantity, unitPrice, discountPct, subtotal: st, vat, total }) => ({ account, description, quantity: Number(quantity), unitPrice: Number(unitPrice), discountPct: Number(discountPct), subtotal: st, vat, total })),
        subtotal, vatTotal, grandTotal, journalEntryId: entryId,
      },
    ]);
    setLines([{ account: PURCHASE_LINE_ACCOUNTS[0], description: "", quantity: 1, unitPrice: "", discountPct: 0 }]); setReason("");
  };

  return (
    <div>
      <div className="panel form-panel">
        <div className="form-grid header-grid">
          <label>المورد<select value={supplierId} onChange={(e) => setSupplierId(Number(e.target.value))}>{companySuppliers.map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}</select></label>
          <label>تاريخ المردود<input type="date" value={date} onChange={(e) => setDate(e.target.value)} /></label>
          <label className="memo-field">سبب المردود<input type="text" value={reason} onChange={(e) => setReason(e.target.value)} /></label>
        </div>
        <div className="lines-table-wrap">
          <table className="lines-table">
            <thead><tr><th>الحساب</th><th>الوصف</th><th>الكمية</th><th>سعر الوحدة</th><th>خصم %</th><th>الإجمالي شامل الضريبة</th><th></th></tr></thead>
            <tbody>
              {computedLines.map((l, idx) => (
                <tr key={idx}>
                  <td><select value={l.account} onChange={(e) => updateLine(idx, "account", e.target.value)}>{PURCHASE_LINE_ACCOUNTS.map((a) => <option key={a} value={a}>{a}</option>)}</select></td>
                  <td><input type="text" value={l.description} onChange={(e) => updateLine(idx, "description", e.target.value)} /></td>
                  <td><input type="number" className="amount-input" value={l.quantity} onChange={(e) => updateLine(idx, "quantity", e.target.value)} /></td>
                  <td><input type="number" className="amount-input" value={l.unitPrice} onChange={(e) => updateLine(idx, "unitPrice", e.target.value)} /></td>
                  <td><input type="number" className="amount-input" value={l.discountPct} onChange={(e) => updateLine(idx, "discountPct", e.target.value)} /></td>
                  <td className="num">{fmt2(l.total)}</td>
                  <td><button className="btn-remove-line" onClick={() => removeLine(idx)} disabled={lines.length <= 1}>✕</button></td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        <div className="preview-box">
          <div className="preview-row"><span>قبل الضريبة</span><strong>{fmt(subtotal)} ر.س</strong></div>
          <div className="preview-row"><span>ضريبة القيمة المضافة</span><strong>{fmt(vatTotal)} ر.س</strong></div>
          <div className="preview-row net-row"><span>إجمالي المردود</span><strong>{fmt(grandTotal)} ر.س</strong></div>
        </div>
        <div className="journal-actions">
          <button className="btn-ghost" onClick={addLine}>+ إضافة سطر</button>
          <button className="btn-primary" onClick={saveReturn} disabled={!supplier || grandTotal <= 0}>حفظ وترحيل المردود</button>
        </div>
      </div>

      <div className="entries-feed">
        {list.slice().reverse().map((r) => {
          const s = suppliers.find((x) => x.id === r.supplierId);
          return (
            <div className="panel entry-card" key={r.id}>
              <div className="entry-card-head">
                <div><span className="entry-memo">{r.returnNumber} — {s?.name}</span><span className="entry-meta">{r.date} {r.reason ? `· ${r.reason}` : ""}</span></div>
                <span className="entry-total">-{fmt(r.grandTotal)} ر.س</span>
              </div>
              <div className="entry-card-actions"><button className="btn-ghost" onClick={() => setPreviewReturn(r)}>معاينة / طباعة</button></div>
            </div>
          );
        })}
        {list.length === 0 && <p className="empty">لا توجد مردودات مسجّلة بعد.</p>}
      </div>

      {previewReturn && (() => {
        const s = suppliers.find((x) => x.id === previewReturn.supplierId);
        const company = COMPANIES.find((x) => x.id === previewReturn.company);
        return (
          <PrintShell subtitle="إشعار مدين — مردود مشتريات" company={company} refNode={<><div>رقم المردود: <strong>{previewReturn.returnNumber}</strong></div><div>التاريخ: <strong>{previewReturn.date}</strong></div></>} onClose={() => setPreviewReturn(null)}>
            <div className="voucher-meta"><div><span>المورد</span><strong>{s?.name}</strong></div><div><span>السبب</span><strong>{previewReturn.reason || "—"}</strong></div></div>
            <table className="ledger-table voucher-table">
              <thead><tr><th>الوصف</th><th>الكمية</th><th>قبل الضريبة</th><th>الضريبة</th><th>الإجمالي</th></tr></thead>
              <tbody>{previewReturn.lines.map((l, i) => (<tr key={i}><td>{l.description || l.account}</td><td className="num">{l.quantity}</td><td className="num">{fmt(l.subtotal)}</td><td className="num">{fmt(l.vat)}</td><td className="num strong">{fmt(l.total)}</td></tr>))}</tbody>
              <tfoot><tr><td className="foot-label" colSpan={4}>الإجمالي</td><td className="num strong">{fmt(previewReturn.grandTotal)}</td></tr></tfoot>
            </table>
          </PrintShell>
        );
      })()}
    </div>
  );
}

/* ============ المشتريات: التقارير ============ */

const PURCHASE_REPORT_TABS = [
  { id: "bySupplier", label: "حسب المورد" },
  { id: "monthly", label: "الاتجاه الشهري" },
  { id: "aging", label: "أعمار الذمم الدائنة" },
  { id: "vat", label: "ملخص الضريبة" },
];

function PurchaseReportsModule({ suppliers, invoices, returns, entries, companyId }) {
  const [tab, setTab] = useState("bySupplier");
  const companySuppliers = companyId === "all" ? suppliers : suppliers.filter((s) => s.company === companyId);
  const companyInvoices = invoices.filter((i) => companySuppliers.some((s) => s.id === i.supplierId));
  const companyReturns = returns.filter((r) => companySuppliers.some((s) => s.id === r.supplierId));

  return (
    <div>
      <div className="report-tabs">{PURCHASE_REPORT_TABS.map((t) => (<button key={t.id} className={"report-tab" + (tab === t.id ? " active" : "")} onClick={() => setTab(t.id)}>{t.label}</button>))}</div>

      {tab === "bySupplier" && (
        <div className="panel">
          <h3>المشتريات حسب المورد</h3>
          <table className="ledger-table">
            <thead><tr><th>المورد</th><th>عدد الفواتير</th><th>إجمالي الفواتير</th><th>إجمالي المردودات</th><th>صافي المشتريات</th><th>المستحق له</th></tr></thead>
            <tbody>
              {companySuppliers.map((s) => {
                const supInv = companyInvoices.filter((i) => i.supplierId === s.id);
                const supRet = companyReturns.filter((r) => r.supplierId === s.id);
                const invTotal = supInv.reduce((sm, i) => sm + i.grandTotal, 0);
                const retTotal = supRet.reduce((sm, r) => sm + r.grandTotal, 0);
                const balance = supplierAccountBalance(entries, s.id);
                return (<tr key={s.id}><td>{s.name}</td><td className="num">{supInv.length}</td><td className="num">{fmt(invTotal)}</td><td className="num">{fmt(retTotal)}</td><td className="num strong">{fmt(invTotal - retTotal)}</td><td className="num">{fmt(balance)}</td></tr>);
              })}
            </tbody>
          </table>
          {companySuppliers.length === 0 && <p className="empty">لا يوجد موردون بعد.</p>}
        </div>
      )}

      {tab === "monthly" && (() => {
        const byMonth = {};
        companyInvoices.forEach((i) => {
          const m = i.date.slice(0, 7);
          byMonth[m] = byMonth[m] || { count: 0, subtotal: 0, vat: 0, total: 0 };
          byMonth[m].count += 1; byMonth[m].subtotal += i.subtotal; byMonth[m].vat += i.vatTotal; byMonth[m].total += i.grandTotal;
        });
        const months = Object.keys(byMonth).sort();
        return (
          <div className="panel">
            <h3>اتجاه المشتريات الشهري</h3>
            <table className="ledger-table">
              <thead><tr><th>الشهر</th><th>عدد الفواتير</th><th>قبل الضريبة</th><th>الضريبة</th><th>الإجمالي</th></tr></thead>
              <tbody>{months.map((m) => (<tr key={m}><td>{monthLabel(m)}</td><td className="num">{byMonth[m].count}</td><td className="num">{fmt(byMonth[m].subtotal)}</td><td className="num">{fmt(byMonth[m].vat)}</td><td className="num strong">{fmt(byMonth[m].total)}</td></tr>))}</tbody>
            </table>
            {months.length === 0 && <p className="empty">لا توجد فواتير مسجّلة بعد.</p>}
          </div>
        );
      })()}

      {tab === "aging" && (
        <div className="panel">
          <h3>أعمار الذمم الدائنة (حتى 2026-07-20)</h3>
          <table className="ledger-table">
            <thead><tr><th>المورد</th><th>0-30 يوم</th><th>31-60 يوم</th><th>61-90 يوم</th><th>أكثر من 90 يوم</th><th>الإجمالي</th></tr></thead>
            <tbody>
              {companySuppliers.map((s) => {
                const balance = supplierAccountBalance(entries, s.id);
                if (balance <= 0.5) return null;
                const supInv = companyInvoices.filter((i) => i.supplierId === s.id);
                const b = agingBuckets(supInv, balance, "2026-07-20", "date", "grandTotal");
                return (<tr key={s.id}><td>{s.name}</td><td className="num">{fmt(b.current)}</td><td className="num">{fmt(b.d30)}</td><td className="num">{fmt(b.d60)}</td><td className="num balance-bad">{fmt(b.d90)}</td><td className="num strong">{fmt(balance)}</td></tr>);
              })}
            </tbody>
          </table>
          {companySuppliers.every((s) => supplierAccountBalance(entries, s.id) <= 0.5) && <p className="empty">لا توجد أرصدة مستحقة حالياً.</p>}
        </div>
      )}

      {tab === "vat" && (() => {
        const inputVatInvoices = companyInvoices.reduce((s, i) => s + i.vatTotal, 0);
        const inputVatReturns = companyReturns.reduce((s, r) => s + r.vatTotal, 0);
        const netVat = inputVatInvoices - inputVatReturns;
        return (
          <>
            <div className="gauge-row gauge-row-3">
              <Gauge label="ضريبة مدخلات الفواتير" value={inputVatInvoices} max={100000} unit="ر.س" tone="#2F5D5A" />
              <Gauge label="ضريبة مدخلات المردودات" value={inputVatReturns} max={30000} unit="ر.س" tone="#A8432B" />
              <Gauge label="صافي ضريبة المشتريات القابلة للخصم" value={Math.max(netVat, 0)} max={100000} unit="ر.س" tone="#B98B4E" />
            </div>
            <div className="panel">
              <table className="ledger-table">
                <tbody>
                  <tr><td>إجمالي ضريبة المدخلات على الفواتير</td><td className="num">{fmt(inputVatInvoices)} ر.س</td></tr>
                  <tr><td>إجمالي ضريبة المدخلات على المردودات (تُخصم)</td><td className="num">-{fmt(inputVatReturns)} ر.س</td></tr>
                  <tr className="net-row"><td className="strong">صافي ضريبة المشتريات القابلة للاسترداد/الخصم</td><td className="num strong">{fmt(netVat)} ر.س</td></tr>
                </tbody>
              </table>
            </div>
          </>
        );
      })()}
    </div>
  );
}

const PURCHASE_TABS = [
  { id: "suppliers", label: "الموردون" },
  { id: "invoices", label: "فواتير المشتريات" },
  { id: "returns", label: "مردودات المشتريات" },
  { id: "reports", label: "التقارير" },
];

function PurchasesModule({ suppliers, setSuppliers, invoices, setInvoices, returns, setReturns, entries, setEntries, companyId, tab, setTab, unlockPin }) {
  return (
    <div>
      <div className="section-title"><span className="eyebrow">التوريد والمشتريات</span><h2>المشتريات</h2></div>
      <div className="report-tabs">{PURCHASE_TABS.map((t) => (<button key={t.id} className={"report-tab" + (tab === t.id ? " active" : "")} onClick={() => setTab(t.id)}>{t.label}</button>))}</div>
      {tab === "suppliers" && <SupplierDirectory suppliers={suppliers} setSuppliers={setSuppliers} entries={entries} companyId={companyId} />}
      {tab === "invoices" && <PurchaseInvoiceModule suppliers={suppliers} invoices={invoices} setInvoices={setInvoices} entries={entries} setEntries={setEntries} companyId={companyId} unlockPin={unlockPin} />}
      {tab === "returns" && <PurchaseReturnsModule suppliers={suppliers} invoices={invoices} returns={returns} setReturns={setReturns} entries={entries} setEntries={setEntries} companyId={companyId} />}
      {tab === "reports" && <PurchaseReportsModule suppliers={suppliers} invoices={invoices} returns={returns} entries={entries} companyId={companyId} />}
    </div>
  );
}

/* ============ الحسابات: الإطار العام للوحدة (القيود + مبيعات المحطات + الزكاة) ============ */

const ACCOUNTS_TABS = [
  { id: "journal", label: "القيود اليومية" },
  { id: "chartOfAccounts", label: "شجرة الحسابات" },
  { id: "zakat", label: "الزكاة والضريبة" },
];

function ChartOfAccountsSection({ onDataChange }) {
  const [, forceRerender] = useState(0);
  const [form, setForm] = useState({ name: "", type: "asset" });
  const [editingName, setEditingName] = useState(null);
  const [editForm, setEditForm] = useState({ name: "", type: "asset" });

  const add = () => {
    if (!form.name.trim() || ACCOUNTS.some((a) => a.name === form.name.trim())) return;
    ACCOUNTS.push({ name: form.name.trim(), type: form.type });
    setForm({ name: "", type: "asset" });
    onDataChange(); forceRerender((v) => v + 1);
  };
  const startEdit = (a) => { setEditingName(a.name); setEditForm({ name: a.name, type: a.type }); };
  const saveEdit = () => {
    const idx = ACCOUNTS.findIndex((a) => a.name === editingName);
    if (idx > -1) { ACCOUNTS[idx].name = editForm.name; ACCOUNTS[idx].type = editForm.type; }
    setEditingName(null);
    onDataChange(); forceRerender((v) => v + 1);
  };
  const remove = (name) => {
    if (!window.confirm(`حذف حساب "${name}"؟ لن يؤثر هذا على القيود المرحّلة سابقاً بهذا الاسم.`)) return;
    const idx = ACCOUNTS.findIndex((a) => a.name === name);
    if (idx > -1) ACCOUNTS.splice(idx, 1);
    onDataChange(); forceRerender((v) => v + 1);
  };

  const grouped = ["asset", "liability", "equity", "revenue", "expense"].map((t) => ({ type: t, accounts: ACCOUNTS.filter((a) => a.type === t) }));

  return (
    <div>
      <div className="panel form-panel">
        <div className="form-grid">
          <label>اسم الحساب<input type="text" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} placeholder="مثال: مصروف صيانة معدات" /></label>
          <label>التصنيف<select value={form.type} onChange={(e) => setForm({ ...form, type: e.target.value })}>{Object.entries(TYPE_LABEL).map(([k, v]) => <option key={k} value={k}>{v}</option>)}</select></label>
        </div>
        <button className="btn-primary" onClick={add}>إضافة حساب جديد</button>
      </div>

      {grouped.map((g) => (
        <div className="panel" key={g.type}>
          <h3>{TYPE_LABEL[g.type]}</h3>
          <table className="ledger-table">
            <tbody>
              {g.accounts.map((a) => (
                <tr key={a.name}>
                  {editingName === a.name ? (
                    <>
                      <td><input type="text" value={editForm.name} onChange={(e) => setEditForm({ ...editForm, name: e.target.value })} /></td>
                      <td><select value={editForm.type} onChange={(e) => setEditForm({ ...editForm, type: e.target.value })}>{Object.entries(TYPE_LABEL).map(([k, v]) => <option key={k} value={k}>{v}</option>)}</select></td>
                      <td className="row-actions"><button className="btn-ghost" onClick={saveEdit}>حفظ</button><button className="btn-ghost" onClick={() => setEditingName(null)}>إلغاء</button></td>
                    </>
                  ) : (
                    <>
                      <td>{a.name}</td><td></td>
                      <td className="row-actions">
                        <button className="icon-btn" title="تعديل" onClick={() => startEdit(a)}><Icon.Edit /></button>
                        <button className="icon-btn icon-btn-danger" title="حذف" onClick={() => remove(a.name)}><Icon.Trash /></button>
                      </td>
                    </>
                  )}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      ))}
    </div>
  );
}

function AccountsModule({ entries, setEntries, sales, setSales, companyId, tab, setTab, onDataChange }) {
  return (
    <div>
      <div className="section-title">
        <span className="eyebrow">الدفاتر المحاسبية</span>
        <h2>الحسابات</h2>
      </div>
      <div className="report-tabs">
        {ACCOUNTS_TABS.map((t) => (
          <button key={t.id} className={"report-tab" + (tab === t.id ? " active" : "")} onClick={() => setTab(t.id)}>{t.label}</button>
        ))}
      </div>
      {tab === "journal" && <JournalModule entries={entries} setEntries={setEntries} companyId={companyId} />}
      {tab === "chartOfAccounts" && <ChartOfAccountsSection onDataChange={onDataChange} />}
      {tab === "zakat" && <ZakatModule entries={entries} sales={sales} companyId={companyId} />}
    </div>
  );
}

/* ============ المخزون ============ */

function stockBalance(movements, itemId, warehouseId) {
  return movements
    .filter((m) => m.itemId === itemId && (!warehouseId || m.warehouseId === warehouseId))
    .reduce((s, m) => s + (["in", "transfer_in"].includes(m.type) ? m.quantity : -m.quantity), 0);
}

function ItemsDirectory({ items, setItems, companyId }) {
  const [form, setForm] = useState(emptyItemForm(companyId));
  const [editingId, setEditingId] = useState(null);
  const [searchText, setSearchText] = useState("");
  const [categoryFilter, setCategoryFilter] = useState("");
  const list = companyId === "all" ? items : items.filter((i) => i.company === companyId);

  const resetForm = () => { setEditingId(null); setForm(emptyItemForm(companyId)); };
  const startEdit = (i) => { setEditingId(i.id); setForm({ ...i }); };

  const saveItem = () => {
    if (!form.name || !form.code) return;
    const cleaned = { ...form, costPrice: Number(form.costPrice || 0), reorderLevel: Number(form.reorderLevel || 0) };
    if (editingId) {
      setItems((prev) => prev.map((i) => (i.id === editingId ? { ...i, ...cleaned } : i)));
    } else {
      setItems((prev) => [...prev, { id: prev.length ? Math.max(...prev.map((i) => i.id)) + 1 : 1, ...cleaned }]);
    }
    resetForm();
  };
  const deleteItem = (i) => {
    if (!window.confirm(`حذف الصنف "${i.name}"؟`)) return;
    setItems((prev) => prev.filter((x) => x.id !== i.id));
  };
  const exportItemsCsv = () => {
    const rows = [["الكود", "الاسم", "الشركة", "الوحدة", "التصنيف", "تكلفة الوحدة", "حد الطلب"]];
    list.forEach((i) => rows.push([i.code, i.name, COMPANIES.find((c) => c.id === i.company)?.short, i.unit, i.category, i.costPrice, i.reorderLevel]));
    downloadCsv("الأصناف.csv", rows);
  };

  const categories = [...new Set(list.map((i) => i.category).filter(Boolean))];
  const byCategory = {};
  list.forEach((i) => { byCategory[i.category || "غير مصنّف"] = (byCategory[i.category || "غير مصنّف"] || 0) + 1; });
  const palette = ["#2F5D5A", "#B98B4E", "#3E6B8A", "#8A5A3E", "#A8432B", "#6B4E8A"];
  const filtered = list.filter((i) => {
    if (searchText && !(i.name.includes(searchText) || i.code.includes(searchText))) return false;
    if (categoryFilter && i.category !== categoryFilter) return false;
    return true;
  });

  return (
    <div>
      <div className="panel form-panel">
        {editingId && <div className="edit-banner">تعديل الصنف — {form.name}</div>}
        <div className="form-grid">
          <label>كود الصنف<input type="text" value={form.code} onChange={(e) => setForm({ ...form, code: e.target.value })} placeholder="مثال: OIL-5W30" /></label>
          <label>اسم الصنف<input type="text" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} /></label>
          <label>الشركة<select value={form.company} onChange={(e) => setForm({ ...form, company: e.target.value })}>{COMPANIES.filter((c) => c.id !== "all").map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}</select></label>
          <label>وحدة القياس<select value={form.unit} onChange={(e) => setForm({ ...form, unit: e.target.value })}>{UNITS.map((u) => <option key={u}>{u}</option>)}</select></label>
          <label>التصنيف<input type="text" value={form.category} onChange={(e) => setForm({ ...form, category: e.target.value })} /></label>
          <label>تكلفة الوحدة<input type="number" value={form.costPrice} onChange={(e) => setForm({ ...form, costPrice: e.target.value })} placeholder="0" /></label>
          <label>حد إعادة الطلب<input type="number" value={form.reorderLevel} onChange={(e) => setForm({ ...form, reorderLevel: e.target.value })} placeholder="0" /></label>
        </div>
        <div className="form-btn-group">
          {editingId && <button className="btn-ghost" onClick={resetForm}>إلغاء</button>}
          <button className="btn-primary" onClick={saveItem}>{editingId ? "حفظ التعديلات" : "حفظ الصنف"}</button>
        </div>
      </div>

      {list.length > 0 && (
        <div className="analytics-row">
          <MiniDonut
            title="توزيع الأصناف حسب التصنيف"
            segments={Object.entries(byCategory).map(([label, value], i) => ({ label, value, color: palette[i % palette.length] }))}
          />
        </div>
      )}

      <div className="panel">
        <div className="filter-bar">
          <input type="text" value={searchText} onChange={(e) => setSearchText(e.target.value)} placeholder="بحث بالاسم أو الكود" />
          <select value={categoryFilter} onChange={(e) => setCategoryFilter(e.target.value)}>
            <option value="">كل التصنيفات</option>
            {categories.map((c) => <option key={c} value={c}>{c}</option>)}
          </select>
          <button className="btn-ghost" onClick={exportItemsCsv}>تصدير الكل Excel</button>
        </div>
        <table className="ledger-table">
          <thead><tr><th>الكود</th><th>الاسم</th><th>الشركة</th><th>الوحدة</th><th>التصنيف</th><th>تكلفة الوحدة</th><th>حد الطلب</th><th></th></tr></thead>
          <tbody>
            {filtered.map((i) => (
              <tr key={i.id}>
                <td>{i.code}</td><td>{i.name}</td><td>{COMPANIES.find((c) => c.id === i.company)?.short}</td>
                <td>{i.unit}</td><td>{i.category || "—"}</td><td className="num">{fmt2(i.costPrice)}</td><td className="num">{i.reorderLevel}</td>
                <td className="row-actions">
                  <button className="icon-btn" title="تعديل" onClick={() => startEdit(i)}><Icon.Edit /></button>
                  <button className="icon-btn icon-btn-danger" title="حذف" onClick={() => deleteItem(i)}><Icon.Trash /></button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
        {filtered.length === 0 && <p className="empty">لا توجد أصناف مطابقة.</p>}
      </div>
    </div>
  );
}

function StockInOutModule({ items, movements, setMovements, entries, setEntries, companyId }) {
  const companyItems = companyId === "all" ? items : items.filter((i) => i.company === companyId);
  const companyCC = companyId === "all" ? COST_CENTERS : COST_CENTERS.filter((c) => c.company === "all" || c.company === companyId);
  const [type, setType] = useState("in");
  const [itemId, setItemId] = useState(companyItems[0]?.id || "");
  const [warehouseId, setWarehouseId] = useState(companyCC[0]?.id || "");
  const [quantity, setQuantity] = useState("");
  const [date, setDate] = useState("2026-07-20");
  const [note, setNote] = useState("");

  const item = items.find((i) => i.id === itemId);
  const currentBalance = item ? stockBalance(movements, item.id, warehouseId) : 0;

  const save = () => {
    if (!item || !Number(quantity) || Number(quantity) <= 0) return;
    const qty = Number(quantity);
    const amount = qty * item.costPrice;
    const jLines = type === "in"
      ? [
          { account: "المخزون", costCenter: warehouseId, department: "المشتريات", debit: amount, credit: 0 },
          { account: "تسويات المخزون", costCenter: warehouseId, department: "المالية والحسابات", debit: 0, credit: amount },
        ]
      : [
          { account: "مصروف تالف ونقص المخزون", costCenter: warehouseId, department: "المالية والحسابات", debit: amount, credit: 0 },
          { account: "المخزون", costCenter: warehouseId, department: "المشتريات", debit: 0, credit: amount },
        ];
    const entryId = entries.length ? Math.max(...entries.map((e) => e.id)) + 1 : 1;
    setEntries((prev) => [...prev, { id: entryId, company: item.company, date, memo: `${STOCK_MOVE_TYPES[type]} — ${item.name}`, lines: jLines }]);
    setMovements((prev) => [...prev, { id: prev.length ? Math.max(...prev.map((m) => m.id)) + 1 : 1, date, company: item.company, itemId: item.id, warehouseId, type, quantity: qty, unitCost: item.costPrice, note, journalEntryId: entryId }]);
    setQuantity(""); setNote("");
  };

  return (
    <div>
      <div className="panel form-panel">
        <div className="form-grid">
          <label>الحركة<select value={type} onChange={(e) => setType(e.target.value)}><option value="in">إضافة مخزون</option><option value="out">حذف / إتلاف مخزون</option></select></label>
          <label>الصنف<select value={itemId} onChange={(e) => setItemId(Number(e.target.value))}>{companyItems.map((i) => <option key={i.id} value={i.id}>{i.name}</option>)}</select></label>
          <label>الموقع / المخزن<select value={warehouseId} onChange={(e) => setWarehouseId(e.target.value)}>{companyCC.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}</select></label>
          <label>الكمية<input type="number" value={quantity} onChange={(e) => setQuantity(e.target.value)} /></label>
          <label>التاريخ<input type="date" value={date} onChange={(e) => setDate(e.target.value)} /></label>
          <label className="memo-field">ملاحظة<input type="text" value={note} onChange={(e) => setNote(e.target.value)} placeholder="سبب الحركة" /></label>
        </div>
        {item && <p className="note">الرصيد الحالي لهذا الصنف في هذا الموقع: <strong>{fmt2(currentBalance)} {item.unit}</strong></p>}
        <button className="btn-primary" onClick={save} disabled={!item || !Number(quantity)}>حفظ الحركة</button>
      </div>
      <StockMovementsTable items={items} movements={movements} companyId={companyId} filterTypes={["in", "out"]} />
    </div>
  );
}

function IssueModule({ items, movements, setMovements, entries, setEntries, companyId }) {
  const companyItems = companyId === "all" ? items : items.filter((i) => i.company === companyId);
  const companyCC = companyId === "all" ? COST_CENTERS : COST_CENTERS.filter((c) => c.company === "all" || c.company === companyId);
  const [itemId, setItemId] = useState(companyItems[0]?.id || "");
  const [warehouseId, setWarehouseId] = useState(companyCC[0]?.id || "");
  const [department, setDepartment] = useState(DEPARTMENTS[0]);
  const [quantity, setQuantity] = useState("");
  const [date, setDate] = useState("2026-07-20");
  const [note, setNote] = useState("");

  const item = items.find((i) => i.id === itemId);
  const currentBalance = item ? stockBalance(movements, item.id, warehouseId) : 0;

  const save = () => {
    if (!item || !Number(quantity) || Number(quantity) <= 0 || Number(quantity) > currentBalance) return;
    const qty = Number(quantity);
    const amount = qty * item.costPrice;
    const jLines = [
      { account: "تكلفة البضاعة المباعة / الصرف المخزني", costCenter: warehouseId, department, debit: amount, credit: 0 },
      { account: "المخزون", costCenter: warehouseId, department: "المشتريات", debit: 0, credit: amount },
    ];
    const entryId = entries.length ? Math.max(...entries.map((e) => e.id)) + 1 : 1;
    setEntries((prev) => [...prev, { id: entryId, company: item.company, date, memo: `صرف مخزني — ${item.name} (${department})`, lines: jLines }]);
    setMovements((prev) => [...prev, { id: prev.length ? Math.max(...prev.map((m) => m.id)) + 1 : 1, date, company: item.company, itemId: item.id, warehouseId, type: "issue", quantity: qty, unitCost: item.costPrice, note: `${department} — ${note}`, journalEntryId: entryId }]);
    setQuantity(""); setNote("");
  };

  return (
    <div>
      <div className="panel form-panel">
        <div className="form-grid">
          <label>الصنف<select value={itemId} onChange={(e) => setItemId(Number(e.target.value))}>{companyItems.map((i) => <option key={i.id} value={i.id}>{i.name}</option>)}</select></label>
          <label>الموقع / المخزن<select value={warehouseId} onChange={(e) => setWarehouseId(e.target.value)}>{companyCC.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}</select></label>
          <label>القسم المستفيد<select value={department} onChange={(e) => setDepartment(e.target.value)}>{DEPARTMENTS.map((d) => <option key={d}>{d}</option>)}</select></label>
          <label>الكمية<input type="number" value={quantity} onChange={(e) => setQuantity(e.target.value)} /></label>
          <label>التاريخ<input type="date" value={date} onChange={(e) => setDate(e.target.value)} /></label>
          <label className="memo-field">ملاحظة<input type="text" value={note} onChange={(e) => setNote(e.target.value)} /></label>
        </div>
        {item && <p className="note">الرصيد المتاح: <strong>{fmt2(currentBalance)} {item.unit}</strong> {Number(quantity) > currentBalance && <span className="balance-bad"> — الكمية المطلوبة أكبر من الرصيد المتاح</span>}</p>}
        <button className="btn-primary" onClick={save} disabled={!item || !Number(quantity) || Number(quantity) > currentBalance}>صرف من المخزون</button>
      </div>
      <StockMovementsTable items={items} movements={movements} companyId={companyId} filterTypes={["issue"]} />
    </div>
  );
}

function TransferModule({ items, movements, setMovements, entries, setEntries, companyId }) {
  const [itemId, setItemId] = useState(items[0]?.id || "");
  const [fromWarehouseId, setFromWarehouseId] = useState(COST_CENTERS[0]?.id || "");
  const [toWarehouseId, setToWarehouseId] = useState(COST_CENTERS[1]?.id || "");
  const [toCompany, setToCompany] = useState(items[0]?.company || "tesm");
  const [quantity, setQuantity] = useState("");
  const [date, setDate] = useState("2026-07-20");

  const item = items.find((i) => i.id === itemId);
  const fromBalance = item ? stockBalance(movements, item.id, fromWarehouseId) : 0;
  const crossCompany = item && toCompany !== item.company;

  const save = () => {
    if (!item || !Number(quantity) || Number(quantity) <= 0 || Number(quantity) > fromBalance) return;
    const qty = Number(quantity);
    const amount = qty * item.costPrice;
    const entryId0 = entries.length ? Math.max(...entries.map((e) => e.id)) + 1 : 1;

    if (!crossCompany) {
      const jLines = [
        { account: "المخزون", costCenter: toWarehouseId, department: "المشتريات", debit: amount, credit: 0 },
        { account: "المخزون", costCenter: fromWarehouseId, department: "المشتريات", debit: 0, credit: amount },
      ];
      setEntries((prev) => [...prev, { id: entryId0, company: item.company, date, memo: `تحويل مخزني داخلي — ${item.name}`, lines: jLines }]);
    } else {
      const entrySource = { id: entryId0, company: item.company, date, memo: `تحويل مخزون صادر لشركة أخرى — ${item.name}`, lines: [
        { account: "حساب جاري - شركات المجموعة", costCenter: fromWarehouseId, department: "المالية والحسابات", debit: amount, credit: 0 },
        { account: "المخزون", costCenter: fromWarehouseId, department: "المشتريات", debit: 0, credit: amount },
      ] };
      const entryDest = { id: entryId0 + 1, company: toCompany, date, memo: `تحويل مخزون وارد من شركة أخرى — ${item.name}`, lines: [
        { account: "المخزون", costCenter: toWarehouseId, department: "المشتريات", debit: amount, credit: 0 },
        { account: "حساب جاري - شركات المجموعة", costCenter: toWarehouseId, department: "المالية والحسابات", debit: 0, credit: amount },
      ] };
      setEntries((prev) => [...prev, entrySource, entryDest]);
    }

    setMovements((prev) => [
      ...prev,
      { id: prev.length ? Math.max(...prev.map((m) => m.id)) + 1 : 1, date, company: item.company, itemId: item.id, warehouseId: fromWarehouseId, type: "transfer_out", quantity: qty, unitCost: item.costPrice, note: crossCompany ? `تحويل لشركة ${COMPANIES.find((c) => c.id === toCompany)?.short}` : "تحويل داخلي", journalEntryId: entryId0 },
      { id: (prev.length ? Math.max(...prev.map((m) => m.id)) + 1 : 1) + 1, date, company: toCompany, itemId: item.id, warehouseId: toWarehouseId, type: "transfer_in", quantity: qty, unitCost: item.costPrice, note: "وارد بالتحويل", journalEntryId: entryId0 },
    ]);
    setQuantity("");
  };

  return (
    <div>
      <div className="panel form-panel">
        <div className="form-grid">
          <label>الصنف<select value={itemId} onChange={(e) => setItemId(Number(e.target.value))}>{items.map((i) => <option key={i.id} value={i.id}>{i.name} ({COMPANIES.find((c) => c.id === i.company)?.short})</option>)}</select></label>
          <label>من موقع (المصدر)<select value={fromWarehouseId} onChange={(e) => setFromWarehouseId(e.target.value)}>{COST_CENTERS.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}</select></label>
          <label>الشركة المستقبلة<select value={toCompany} onChange={(e) => setToCompany(e.target.value)}>{COMPANIES.filter((c) => c.id !== "all").map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}</select></label>
          <label>إلى موقع (الوجهة)<select value={toWarehouseId} onChange={(e) => setToWarehouseId(e.target.value)}>{COST_CENTERS.filter((c) => c.company === "all" || c.company === toCompany).map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}</select></label>
          <label>الكمية<input type="number" value={quantity} onChange={(e) => setQuantity(e.target.value)} /></label>
          <label>التاريخ<input type="date" value={date} onChange={(e) => setDate(e.target.value)} /></label>
        </div>
        {item && <p className="note">الرصيد المتاح بالمصدر: <strong>{fmt2(fromBalance)} {item.unit}</strong>{crossCompany && " — تحويل بين شركتين مختلفتين، سيُرحّل عبر حساب جاري بين الشركات ويحتاج مراجعة محاسبية لاحقاً."}</p>}
        <button className="btn-primary" onClick={save} disabled={!item || !Number(quantity) || Number(quantity) > fromBalance}>تنفيذ التحويل</button>
      </div>
      <StockMovementsTable items={items} movements={movements} companyId={companyId} filterTypes={["transfer_out", "transfer_in"]} />
    </div>
  );
}

function StockMovementsTable({ items, movements, companyId, filterTypes }) {
  const list = movements
    .filter((m) => filterTypes.includes(m.type))
    .filter((m) => companyId === "all" || m.company === companyId)
    .slice().reverse();
  return (
    <div className="panel">
      <table className="ledger-table">
        <thead><tr><th>التاريخ</th><th>الصنف</th><th>الحركة</th><th>الموقع</th><th>الكمية</th><th>القيمة</th><th>ملاحظة</th></tr></thead>
        <tbody>
          {list.map((m) => {
            const it = items.find((i) => i.id === m.itemId);
            return (
              <tr key={m.id}>
                <td>{m.date}</td><td>{it?.name}</td><td>{STOCK_MOVE_TYPES[m.type]}</td>
                <td>{costCenterName(m.warehouseId)}</td><td className="num">{fmt2(m.quantity)}</td>
                <td className="num">{fmt(m.quantity * m.unitCost)}</td><td>{m.note || "—"}</td>
              </tr>
            );
          })}
        </tbody>
      </table>
      {list.length === 0 && <p className="empty">لا توجد حركات مسجّلة من هذا النوع بعد.</p>}
    </div>
  );
}

function StockReportModule({ items, movements, companyId }) {
  const companyItems = companyId === "all" ? items : items.filter((i) => i.company === companyId);
  return (
    <div className="panel">
      <h3>أرصدة المخزون الحالية حسب الصنف والموقع</h3>
      <table className="ledger-table">
        <thead><tr><th>الصنف</th><th>الشركة</th><th>الموقع</th><th>الرصيد</th><th>القيمة التقديرية</th></tr></thead>
        <tbody>
          {companyItems.flatMap((it) => {
            const cc = COST_CENTERS.filter((c) => c.company === "all" || c.company === it.company);
            return cc.map((c) => {
              const bal = stockBalance(movements, it.id, c.id);
              if (bal === 0) return null;
              return (
                <tr key={it.id + "-" + c.id}>
                  <td>{it.name}</td><td>{COMPANIES.find((x) => x.id === it.company)?.short}</td>
                  <td>{c.name}</td><td className="num">{fmt2(bal)} {it.unit}</td><td className="num">{fmt(bal * it.costPrice)}</td>
                </tr>
              );
            });
          })}
        </tbody>
      </table>
      {companyItems.every((it) => COST_CENTERS.every((c) => stockBalance(movements, it.id, c.id) === 0)) && <p className="empty">لا توجد أرصدة مخزون مسجّلة بعد.</p>}
    </div>
  );
}

const INVENTORY_TABS = [
  { id: "items", label: "الأصناف" },
  { id: "inout", label: "إضافة / حذف مخزون" },
  { id: "issue", label: "الصرف المخزني" },
  { id: "transfer", label: "التحويل بين الفروع" },
  { id: "stockReport", label: "أرصدة المخزون" },
];

function InventoryModule({ items, setItems, movements, setMovements, entries, setEntries, companyId, tab, setTab }) {
  return (
    <div>
      <div className="section-title"><span className="eyebrow">إدارة المخازن</span><h2>المخزون</h2></div>
      <div className="report-tabs">{INVENTORY_TABS.map((t) => (<button key={t.id} className={"report-tab" + (tab === t.id ? " active" : "")} onClick={() => setTab(t.id)}>{t.label}</button>))}</div>
      {tab === "items" && <ItemsDirectory items={items} setItems={setItems} companyId={companyId} />}
      {tab === "inout" && <StockInOutModule items={items} movements={movements} setMovements={setMovements} entries={entries} setEntries={setEntries} companyId={companyId} />}
      {tab === "issue" && <IssueModule items={items} movements={movements} setMovements={setMovements} entries={entries} setEntries={setEntries} companyId={companyId} />}
      {tab === "transfer" && <TransferModule items={items} movements={movements} setMovements={setMovements} entries={entries} setEntries={setEntries} companyId={companyId} />}
      {tab === "stockReport" && <StockReportModule items={items} movements={movements} companyId={companyId} />}
    </div>
  );
}

/* ============ الإعدادات ============ */

function CompanyDataSettings({ onDataChange }) {
  const editable = COMPANIES.filter((c) => c.id !== "all");
  const [companyId, setCompanyId] = useState(editable[0]?.id);
  const company = COMPANIES.find((c) => c.id === companyId);
  const [form, setForm] = useState({ vatNumber: company?.vatNumber || "", crNumber: company?.crNumber || "", address: company?.address || "" });

  const selectCompany = (id) => {
    setCompanyId(id);
    const c = COMPANIES.find((x) => x.id === id);
    setForm({ vatNumber: c?.vatNumber || "", crNumber: c?.crNumber || "", address: c?.address || "" });
  };

  const save = () => {
    const c = COMPANIES.find((x) => x.id === companyId);
    if (!c) return;
    c.vatNumber = form.vatNumber; c.crNumber = form.crNumber; c.address = form.address;
    onDataChange();
  };

  return (
    <div className="panel form-panel">
      <div className="form-grid">
        <label>الشركة<select value={companyId} onChange={(e) => selectCompany(e.target.value)}>{editable.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}</select></label>
        <label>الرقم الضريبي (15 رقم)<input type="text" maxLength={15} value={form.vatNumber} onChange={(e) => setForm({ ...form, vatNumber: e.target.value.replace(/\D/g, "") })} placeholder="3xxxxxxxxxxxxx3" /></label>
        <label>رقم السجل التجاري<input type="text" value={form.crNumber} onChange={(e) => setForm({ ...form, crNumber: e.target.value })} /></label>
        <label className="memo-field">العنوان الوطني الكامل<input type="text" value={form.address} onChange={(e) => setForm({ ...form, address: e.target.value })} placeholder="رقم المبنى، الشارع، الحي، المدينة، الرمز البريدي" /></label>
      </div>
      <button className="btn-primary" onClick={save}>حفظ بيانات الشركة</button>
      <p className="note">هذه البيانات تظهر تلقائياً في رأس كل الفواتير والمستندات المطبوعة لهذه الشركة.</p>
    </div>
  );
}

function MyProfileSettings({ currentUser, setCurrentUser }) {
  const [form, setForm] = useState(currentUser);
  const save = () => setCurrentUser(form);
  return (
    <div className="panel form-panel">
      <div className="form-grid">
        <label>الاسم الكامل<input type="text" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} /></label>
        <label>البريد الإلكتروني<input type="email" value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} /></label>
        <label>الدور الوظيفي<select value={form.role} onChange={(e) => setForm({ ...form, role: e.target.value })}>{PERMISSION_ROLES.map((r) => <option key={r}>{r}</option>)}</select></label>
      </div>
      <button className="btn-primary" onClick={save}>حفظ الملف الشخصي</button>
    </div>
  );
}

function emptyUserForm() { return { name: "", email: "", role: PERMISSION_ROLES[PERMISSION_ROLES.length - 1], company: "all", active: true }; }

function UsersSettings({ users, setUsers, unlockPin, setUnlockPin }) {
  const [form, setForm] = useState(emptyUserForm());
  const [pinForm, setPinForm] = useState(unlockPin);
  const [activatingId, setActivatingId] = useState(null);
  const [activatePwd, setActivatePwd] = useState("");

  const inviteUser = () => {
    if (!form.name || !form.email) return;
    setUsers((prev) => [...prev, { id: prev.length ? Math.max(...prev.map((u) => u.id)) + 1 : 1, ...form, active: false, password: null, inviteStatus: "pending" }]);
    setForm(emptyUserForm());
  };
  const toggleActive = (id) => setUsers((prev) => prev.map((u) => (u.id === id ? { ...u, active: !u.active } : u)));
  const removeUser = (id) => setUsers((prev) => prev.filter((u) => u.id !== id));
  const confirmActivate = (id) => {
    if (!activatePwd) return;
    setUsers((prev) => prev.map((u) => (u.id === id ? { ...u, password: activatePwd, active: true, inviteStatus: "accepted" } : u)));
    setActivatingId(null); setActivatePwd("");
  };

  return (
    <div>
      <div className="panel form-panel">
        <div className="form-grid">
          <label>الرقم السري لفك ترحيل المعاملات<input type="password" value={pinForm} onChange={(e) => setPinForm(e.target.value)} /></label>
        </div>
        <button className="btn-primary" onClick={() => setUnlockPin(pinForm)}>حفظ الرقم السري</button>
        <p className="note">هذا الرقم مطلوب لفك ترحيل أي كشف رواتب أو معاملة مرحّلة — احتفظ به لدى المخوّلين فقط.</p>
      </div>
      <div className="panel form-panel">
        <div className="form-grid">
          <label>الاسم<input type="text" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} /></label>
          <label>البريد الإلكتروني<input type="email" value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} /></label>
          <label>الصلاحية<select value={form.role} onChange={(e) => setForm({ ...form, role: e.target.value })}>{PERMISSION_ROLES.map((r) => <option key={r}>{r}</option>)}</select></label>
          <label>نطاق الوصول (الشركة)<select value={form.company} onChange={(e) => setForm({ ...form, company: e.target.value })}>{COMPANIES.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}</select></label>
        </div>
        <button className="btn-primary" onClick={inviteUser}>إرسال دعوة لمستخدم جديد</button>
        <p className="note">
          في نظام حقيقي متصل بخادم بريد، سيصل للمستخدم إيميل تلقائي فيه رابط لتفعيل حسابه وتعيين كلمة مرور.
          بما أن هذا عرض تجريبي بدون خادم بريد فعلي، استخدم زر "محاكاة تفعيل الدعوة" أدناه لتعيين كلمة مرور للمستخدم مباشرة.
        </p>
      </div>
      <div className="panel">
        <table className="ledger-table">
          <thead><tr><th>الاسم</th><th>البريد الإلكتروني</th><th>الصلاحية</th><th>نطاق الوصول</th><th>حالة الدعوة</th><th>الحالة</th><th></th></tr></thead>
          <tbody>
            {users.map((u) => (
              <tr key={u.id}>
                <td>{u.name}</td><td>{u.email}</td><td>{u.role}</td>
                <td>{COMPANIES.find((c) => c.id === u.company)?.name}</td>
                <td>{u.inviteStatus === "pending" ? <span className="status-badge">بانتظار التفعيل</span> : <span className="status-badge posted-badge">مفعّل</span>}</td>
                <td><span className="status-badge">{u.active ? "نشط" : "معطّل"}</span></td>
                <td className="row-actions">
                  {u.inviteStatus === "pending" ? (
                    activatingId === u.id ? (
                      <span className="inline-disb">
                        <input type="password" placeholder="كلمة مرور جديدة" value={activatePwd} onChange={(e) => setActivatePwd(e.target.value)} />
                        <button className="btn-primary" onClick={() => confirmActivate(u.id)}>تأكيد</button>
                      </span>
                    ) : (
                      <button className="btn-ghost" onClick={() => setActivatingId(u.id)}>محاكاة تفعيل الدعوة</button>
                    )
                  ) : (
                    <button className="btn-ghost" onClick={() => toggleActive(u.id)}>{u.active ? "تعطيل" : "تفعيل"}</button>
                  )}
                  <button className="btn-ghost" onClick={() => removeUser(u.id)}>حذف</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

function JobTitlesSettings({ jobTitles, setJobTitles }) {
  const [title, setTitle] = useState("");
  const add = () => { if (!title.trim()) return; setJobTitles((prev) => [...prev, title.trim()]); setTitle(""); };
  const remove = (t) => setJobTitles((prev) => prev.filter((x) => x !== t));
  return (
    <div>
      <div className="panel form-panel">
        <div className="form-grid">
          <label className="memo-field">مسمّى وظيفي جديد<input type="text" value={title} onChange={(e) => setTitle(e.target.value)} placeholder="مثال: مشرف مبيعات" /></label>
        </div>
        <button className="btn-primary" onClick={add}>إضافة</button>
      </div>
      <div className="panel">
        <div className="tag-cloud">
          {jobTitles.map((t) => (
            <span key={t} className="tag-chip">{t}<button onClick={() => remove(t)}>✕</button></span>
          ))}
        </div>
        {jobTitles.length === 0 && <p className="empty">لا توجد مسمّيات وظيفية مسجّلة بعد.</p>}
      </div>
    </div>
  );
}

function LocationsSettings({ onDataChange }) {
  const [form, setForm] = useState({ name: "", company: "tesm" });
  const [, forceRerender] = useState(0);

  const add = () => {
    if (!form.name) return;
    COST_CENTERS.push({ id: "cc-" + Date.now(), name: form.name, company: form.company });
    setForm({ name: "", company: form.company });
    onDataChange(); forceRerender((v) => v + 1);
  };
  const remove = (id) => {
    const idx = COST_CENTERS.findIndex((c) => c.id === id);
    if (idx > -1) COST_CENTERS.splice(idx, 1);
    onDataChange(); forceRerender((v) => v + 1);
  };

  return (
    <div>
      <div className="panel form-panel">
        <div className="form-grid">
          <label>اسم الموقع / الفرع<input type="text" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} placeholder="مثال: محطة الروضة الجديدة" /></label>
          <label>الشركة<select value={form.company} onChange={(e) => setForm({ ...form, company: e.target.value })}>
            <option value="all">عام لكل الشركات</option>
            {COMPANIES.filter((c) => c.id !== "all").map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}
          </select></label>
        </div>
        <button className="btn-primary" onClick={add}>إضافة موقع</button>
      </div>
      <div className="panel">
        <table className="ledger-table">
          <thead><tr><th>الموقع</th><th>الشركة</th><th></th></tr></thead>
          <tbody>
            {COST_CENTERS.map((c) => (
              <tr key={c.id}>
                <td>{c.name}</td><td>{c.company === "all" ? "عام" : COMPANIES.find((x) => x.id === c.company)?.name}</td>
                <td><button className="btn-ghost" onClick={() => remove(c.id)}>حذف</button></td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <p className="note">هذه المواقع تُستخدم كمراكز تكلفة في القيود، ومخازن في وحدة المخزون، وأفرع للموظفين.</p>
    </div>
  );
}

function CompanyDocumentsSettings({ companyDocuments, setCompanyDocuments }) {
  const [form, setForm] = useState({ company: "tesm", docType: COMPANY_DOC_TYPES[0], location: "", number: "", expiryDate: "" });
  const locationOptions = COST_CENTERS.filter((c) => c.company === "all" || c.company === form.company);

  const add = () => {
    if (!form.number) return;
    setCompanyDocuments((prev) => [...prev, { id: prev.length ? Math.max(...prev.map((d) => d.id)) + 1 : 1, ...form }]);
    setForm((f) => ({ ...f, number: "", expiryDate: "" }));
  };
  const remove = (id) => setCompanyDocuments((prev) => prev.filter((d) => d.id !== id));

  return (
    <div>
      <div className="panel form-panel">
        <div className="form-grid">
          <label>الشركة<select value={form.company} onChange={(e) => setForm({ ...form, company: e.target.value, location: "" })}>{COMPANIES.filter((c) => c.id !== "all").map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}</select></label>
          <label>نوع المستند<select value={form.docType} onChange={(e) => setForm({ ...form, docType: e.target.value })}>{COMPANY_DOC_TYPES.map((t) => <option key={t}>{t}</option>)}</select></label>
          <label>الموقع (اختياري — للمستندات الخاصة بموقع مثل الدفاع المدني)
            <select value={form.location} onChange={(e) => setForm({ ...form, location: e.target.value })}>
              <option value="">— عام للشركة —</option>
              {locationOptions.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}
            </select>
          </label>
          <label>رقم المستند<input type="text" value={form.number} onChange={(e) => setForm({ ...form, number: e.target.value })} /></label>
          <label>تاريخ الانتهاء<input type="date" value={form.expiryDate} onChange={(e) => setForm({ ...form, expiryDate: e.target.value })} /></label>
        </div>
        <button className="btn-primary" onClick={add}>حفظ المستند</button>
      </div>
      <div className="panel">
        <table className="ledger-table">
          <thead><tr><th>الشركة</th><th>نوع المستند</th><th>الموقع</th><th>الرقم</th><th>تاريخ الانتهاء</th><th></th></tr></thead>
          <tbody>
            {companyDocuments.map((d) => {
              const days = d.expiryDate ? daysUntil(d.expiryDate) : null;
              const cls = days == null ? "" : days < 0 ? "balance-bad" : days <= 30 ? "doc-warning-text" : "";
              return (
                <tr key={d.id}>
                  <td>{COMPANIES.find((c) => c.id === d.company)?.name}</td>
                  <td>{d.docType}</td>
                  <td>{d.location ? costCenterName(d.location) : "عام"}</td>
                  <td>{d.number}</td>
                  <td className={cls}>{d.expiryDate || "—"}</td>
                  <td><button className="btn-ghost" onClick={() => remove(d.id)}>حذف</button></td>
                </tr>
              );
            })}
          </tbody>
        </table>
        {companyDocuments.length === 0 && <p className="empty">لا توجد مستندات رسمية مسجّلة بعد.</p>}
      </div>
    </div>
  );
}

const SETTINGS_TABS = [
  { id: "companies", label: "بيانات الشركات" },
  { id: "profile", label: "الملف الشخصي" },
  { id: "users", label: "المستخدمون والصلاحيات" },
  { id: "jobTitles", label: "الوظائف" },
  { id: "locations", label: "المواقع" },
  { id: "companyDocs", label: "المستندات الرسمية" },
];

function SettingsModule({ tab, setTab, users, setUsers, currentUser, setCurrentUser, jobTitles, setJobTitles, unlockPin, setUnlockPin, companyDocuments, setCompanyDocuments, onDataChange }) {
  return (
    <div>
      <div className="section-title"><span className="eyebrow">إدارة النظام</span><h2>الإعدادات</h2></div>
      <div className="report-tabs">{SETTINGS_TABS.map((t) => (<button key={t.id} className={"report-tab" + (tab === t.id ? " active" : "")} onClick={() => setTab(t.id)}>{t.label}</button>))}</div>
      {tab === "companies" && <CompanyDataSettings onDataChange={onDataChange} />}
      {tab === "profile" && <MyProfileSettings currentUser={currentUser} setCurrentUser={setCurrentUser} />}
      {tab === "users" && <UsersSettings users={users} setUsers={setUsers} unlockPin={unlockPin} setUnlockPin={setUnlockPin} />}
      {tab === "jobTitles" && <JobTitlesSettings jobTitles={jobTitles} setJobTitles={setJobTitles} />}
      {tab === "locations" && <LocationsSettings onDataChange={onDataChange} />}
      {tab === "companyDocs" && <CompanyDocumentsSettings companyDocuments={companyDocuments} setCompanyDocuments={setCompanyDocuments} />}
    </div>
  );
}

/* ============ الأصول الثابتة ============ */

function emptyAssetForm(companyId) {
  return { name: "", category: ASSET_CATEGORIES[0], company: companyId === "all" ? "tesm" : companyId, purchaseDate: "2026-07-20", cost: "", usefulLifeYears: 5, salvageValue: "0", paymentMethod: "cash" };
}

function AssetRegisterModule({ assets, setAssets, entries, setEntries, companyId }) {
  const [form, setForm] = useState(emptyAssetForm(companyId));
  const [editingId, setEditingId] = useState(null);
  const list = companyId === "all" ? assets : assets.filter((a) => a.company === companyId);

  const resetForm = () => { setEditingId(null); setForm(emptyAssetForm(companyId)); };
  const startEdit = (a) => { if (a.status === "disposed") return; setEditingId(a.id); setForm({ ...a }); };

  const saveAsset = () => {
    if (!form.name || !form.cost) return;
    const cleaned = { ...form, cost: Number(form.cost), usefulLifeYears: Number(form.usefulLifeYears), salvageValue: Number(form.salvageValue || 0) };
    if (editingId) {
      setAssets((prev) => prev.map((a) => (a.id === editingId ? { ...a, ...cleaned } : a)));
      resetForm();
      return;
    }
    const creditAccount = form.paymentMethod === "cash" ? "النقدية بالصندوق" : form.paymentMethod === "bank" ? "البنك الأهلي - حساب تشغيلي" : "ذمم دائنة - موردين";
    const jLines = [
      { account: "الأصول الثابتة", costCenter: "", department: "المالية والحسابات", debit: cleaned.cost, credit: 0 },
      { account: creditAccount, costCenter: "", department: "المالية والحسابات", debit: 0, credit: cleaned.cost },
    ];
    const entryId = entries.length ? Math.max(...entries.map((e) => e.id)) + 1 : 1;
    setEntries((prev) => [...prev, { id: entryId, company: cleaned.company, date: cleaned.purchaseDate, memo: `شراء أصل ثابت — ${cleaned.name}`, lines: jLines }]);
    setAssets((prev) => [...prev, { id: prev.length ? Math.max(...prev.map((a) => a.id)) + 1 : 1, ...cleaned, status: "active", journalEntryId: entryId }]);
    resetForm();
  };

  const [searchText, setSearchText] = useState("");
  const [categoryFilter, setCategoryFilter] = useState("");

  return (
    <div>
      <div className="panel form-panel">
        {editingId && <div className="edit-banner">تعديل الأصل — {form.name}</div>}
        <div className="form-grid">
          <label>اسم الأصل<input type="text" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} /></label>
          <label>التصنيف<select value={form.category} onChange={(e) => setForm({ ...form, category: e.target.value })}>{ASSET_CATEGORIES.map((c) => <option key={c}>{c}</option>)}</select></label>
          <label>الشركة<select value={form.company} onChange={(e) => setForm({ ...form, company: e.target.value })}>{COMPANIES.filter((c) => c.id !== "all").map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}</select></label>
          <label>تاريخ الشراء<input type="date" value={form.purchaseDate} onChange={(e) => setForm({ ...form, purchaseDate: e.target.value })} /></label>
          <label>التكلفة<input type="number" value={form.cost} onChange={(e) => setForm({ ...form, cost: e.target.value })} /></label>
          <label>العمر الإنتاجي (سنوات)<input type="number" value={form.usefulLifeYears} onChange={(e) => setForm({ ...form, usefulLifeYears: e.target.value })} /></label>
          <label>القيمة التخريدية<input type="number" value={form.salvageValue} onChange={(e) => setForm({ ...form, salvageValue: e.target.value })} /></label>
          {!editingId && <label>طريقة السداد<select value={form.paymentMethod} onChange={(e) => setForm({ ...form, paymentMethod: e.target.value })}><option value="cash">نقدي</option><option value="bank">بنكي</option><option value="credit">آجل (ذمم دائنة)</option></select></label>}
        </div>
        <div className="form-btn-group">
          {editingId && <button className="btn-ghost" onClick={resetForm}>إلغاء</button>}
          <button className="btn-primary" onClick={saveAsset}>{editingId ? "حفظ التعديلات" : "حفظ الأصل وترحيل الشراء"}</button>
        </div>
      </div>

      {list.length > 0 && (() => {
        const activeCount = list.filter((a) => a.status !== "disposed").length;
        const disposedCount = list.length - activeCount;
        const byCategory = {};
        list.forEach((a) => { byCategory[a.category] = (byCategory[a.category] || 0) + a.cost; });
        const palette = ["#2F5D5A", "#B98B4E", "#3E6B8A", "#8A5A3E", "#A8432B", "#6B4E8A"];
        return (
          <div className="analytics-row">
            <MiniDonut title="الأصول حسب الحالة" segments={[{ label: "نشط", value: activeCount, color: "#2F5D5A" }, { label: "مستبعد", value: disposedCount, color: "#A8432B" }]} />
            <MiniBarChart title="تكلفة الأصول حسب التصنيف" bars={Object.entries(byCategory).map(([label, value], i) => ({ label, value, color: palette[i % palette.length] }))} />
          </div>
        );
      })()}

      <div className="panel">
        <div className="filter-bar">
          <input type="text" value={searchText} onChange={(e) => setSearchText(e.target.value)} placeholder="بحث باسم الأصل" />
          <select value={categoryFilter} onChange={(e) => setCategoryFilter(e.target.value)}>
            <option value="">كل التصنيفات</option>
            {ASSET_CATEGORIES.map((c) => <option key={c}>{c}</option>)}
          </select>
        </div>
        <table className="ledger-table">
          <thead><tr><th>الأصل</th><th>التصنيف</th><th>الشركة</th><th>تاريخ الشراء</th><th>التكلفة</th><th>مجمع الإهلاك</th><th>صافي القيمة الدفترية</th><th>الحالة</th><th></th></tr></thead>
          <tbody>
            {list.filter((a) => (!searchText || a.name.includes(searchText)) && (!categoryFilter || a.category === categoryFilter)).map((a) => {
              const accDep = assetAccumulatedDepreciation(a, "2026-07-20");
              const nbv = a.cost - accDep;
              return (
                <tr key={a.id}>
                  <td>{a.name}</td><td>{a.category}</td><td>{COMPANIES.find((c) => c.id === a.company)?.short}</td>
                  <td>{a.purchaseDate}</td><td className="num">{fmt(a.cost)}</td><td className="num">{fmt(accDep)}</td>
                  <td className="num strong">{fmt(nbv)}</td>
                  <td><span className="status-badge">{a.status === "disposed" ? "مستبعد" : "نشط"}</span></td>
                  <td>{a.status !== "disposed" && <button className="icon-btn" title="تعديل" onClick={() => startEdit(a)}><Icon.Edit /></button>}</td>
                </tr>
              );
            })}
          </tbody>
        </table>
        {list.length === 0 && <p className="empty">لا توجد أصول ثابتة مسجّلة بعد.</p>}
      </div>
    </div>
  );
}

function DepreciationModule({ assets, depreciationRuns, setDepreciationRuns, entries, setEntries, companyId }) {
  const [month, setMonth] = useState("2026-07");
  const companyAssets = (companyId === "all" ? assets : assets.filter((a) => a.company === companyId)).filter((a) => a.status !== "disposed");
  const existingRun = companyId !== "all" ? depreciationRuns.find((r) => r.company === companyId && r.month === month) : null;

  const rows = companyAssets.map((a) => {
    const monthly = a.usefulLifeYears > 0 ? (a.cost - (a.salvageValue || 0)) / a.usefulLifeYears / 12 : 0;
    return { asset: a, monthly };
  });
  const total = rows.reduce((s, r) => s + r.monthly, 0);

  const postDepreciation = () => {
    if (companyId === "all" || existingRun || total <= 0) return;
    const jLines = [
      { account: "مصروف إهلاك الأصول الثابتة", costCenter: "", department: "المالية والحسابات", debit: total, credit: 0 },
      { account: "مجمع الإهلاك", costCenter: "", department: "المالية والحسابات", debit: 0, credit: total },
    ];
    const entryId = entries.length ? Math.max(...entries.map((e) => e.id)) + 1 : 1;
    setEntries((prev) => [...prev, { id: entryId, company: companyId, date: `${month}-28`, memo: `إهلاك شهر ${monthLabel(month)}`, lines: jLines }]);
    setDepreciationRuns((prev) => [...prev, { id: prev.length ? Math.max(...prev.map((r) => r.id)) + 1 : 1, company: companyId, month, totalAmount: total, journalEntryId: entryId }]);
  };

  return (
    <div>
      <div className="panel form-panel">
        <div className="form-grid"><label>الشهر<input type="month" value={month} onChange={(e) => setMonth(e.target.value)} /></label></div>
        {companyId === "all" && <p className="empty">اختر شركة محددة من أيقونات لوحة القيادة لترحيل إهلاك الشهر.</p>}
        {existingRun && <p className="note">تم ترحيل إهلاك هذا الشهر مسبقاً بمبلغ {fmt(existingRun.totalAmount)} ر.س.</p>}
        <button className="btn-primary" onClick={postDepreciation} disabled={companyId === "all" || !!existingRun || total <= 0}>ترحيل إهلاك {monthLabel(month)}</button>
      </div>
      <div className="panel">
        <table className="ledger-table">
          <thead><tr><th>الأصل</th><th>التكلفة</th><th>العمر الإنتاجي</th><th>الإهلاك الشهري</th></tr></thead>
          <tbody>{rows.map((r) => (<tr key={r.asset.id}><td>{r.asset.name}</td><td className="num">{fmt(r.asset.cost)}</td><td className="num">{r.asset.usefulLifeYears} سنة</td><td className="num">{fmt(r.monthly)}</td></tr>))}</tbody>
          <tfoot><tr><td className="foot-label" colSpan={3}>الإجمالي</td><td className="num strong">{fmt(total)}</td></tr></tfoot>
        </table>
        {rows.length === 0 && <p className="empty">لا توجد أصول نشطة لحساب إهلاكها.</p>}
      </div>
    </div>
  );
}

function DisposalModule({ assets, setAssets, entries, setEntries, companyId }) {
  const companyAssets = (companyId === "all" ? assets : assets.filter((a) => a.company === companyId)).filter((a) => a.status !== "disposed");
  const [assetId, setAssetId] = useState(companyAssets[0]?.id || "");
  const [disposalDate, setDisposalDate] = useState("2026-07-20");
  const [salePrice, setSalePrice] = useState("0");
  const [method, setMethod] = useState("cash");

  const asset = assets.find((a) => a.id === assetId);
  const accDep = asset ? assetAccumulatedDepreciation(asset, disposalDate) : 0;
  const nbv = asset ? asset.cost - accDep : 0;
  const gainLoss = Number(salePrice || 0) - nbv;

  const disposeAsset = () => {
    if (!asset) return;
    const receiveAccount = method === "cash" ? "النقدية بالصندوق" : "البنك الأهلي - حساب تشغيلي";
    const jLines = [
      { account: "مجمع الإهلاك", costCenter: "", department: "المالية والحسابات", debit: accDep, credit: 0 },
    ];
    if (Number(salePrice) > 0) jLines.push({ account: receiveAccount, costCenter: "", department: "المالية والحسابات", debit: Number(salePrice), credit: 0 });
    if (gainLoss > 0) jLines.push({ account: "أرباح استبعاد أصول", costCenter: "", department: "المالية والحسابات", debit: 0, credit: gainLoss });
    if (gainLoss < 0) jLines.push({ account: "خسائر استبعاد أصول", costCenter: "", department: "المالية والحسابات", debit: -gainLoss, credit: 0 });
    jLines.push({ account: "الأصول الثابتة", costCenter: "", department: "المالية والحسابات", debit: 0, credit: asset.cost });

    const entryId = entries.length ? Math.max(...entries.map((e) => e.id)) + 1 : 1;
    setEntries((prev) => [...prev, { id: entryId, company: asset.company, date: disposalDate, memo: `استبعاد أصل — ${asset.name}`, lines: jLines }]);
    setAssets((prev) => prev.map((a) => (a.id === asset.id ? { ...a, status: "disposed", disposalDate, disposalValue: Number(salePrice) } : a)));
  };

  return (
    <div>
      <div className="panel form-panel">
        <div className="form-grid">
          <label>الأصل<select value={assetId} onChange={(e) => setAssetId(Number(e.target.value))}>{companyAssets.map((a) => <option key={a.id} value={a.id}>{a.name}</option>)}</select></label>
          <label>تاريخ الاستبعاد<input type="date" value={disposalDate} onChange={(e) => setDisposalDate(e.target.value)} /></label>
          <label>سعر البيع (صفر إن كان إتلافاً)<input type="number" value={salePrice} onChange={(e) => setSalePrice(e.target.value)} /></label>
          <label>طريقة الاستلام<select value={method} onChange={(e) => setMethod(e.target.value)}><option value="cash">نقدي</option><option value="bank">بنكي</option></select></label>
        </div>
        {asset && (
          <div className="preview-box">
            <div className="preview-row"><span>مجمع الإهلاك حتى تاريخ الاستبعاد</span><strong>{fmt(accDep)} ر.س</strong></div>
            <div className="preview-row"><span>صافي القيمة الدفترية</span><strong>{fmt(nbv)} ر.س</strong></div>
            <div className="preview-row net-row"><span>{gainLoss >= 0 ? "ربح الاستبعاد" : "خسارة الاستبعاد"}</span><strong>{fmt(Math.abs(gainLoss))} ر.س</strong></div>
          </div>
        )}
        <button className="btn-primary" onClick={disposeAsset} disabled={!asset}>ترحيل الاستبعاد</button>
        {companyAssets.length === 0 && <p className="empty">لا توجد أصول نشطة لاستبعادها.</p>}
      </div>
    </div>
  );
}

function AssetReportsModule({ assets, companyId }) {
  const list = companyId === "all" ? assets : assets.filter((a) => a.company === companyId);
  const totals = list.reduce((s, a) => {
    const dep = assetAccumulatedDepreciation(a, "2026-07-20");
    s.cost += a.cost; s.dep += dep; s.nbv += a.cost - dep;
    return s;
  }, { cost: 0, dep: 0, nbv: 0 });

  return (
    <div>
      <div className="gauge-row gauge-row-3">
        <Gauge label="إجمالي تكلفة الأصول" value={totals.cost} max={500000} unit="ر.س" tone="#2F5D5A" />
        <Gauge label="مجمع الإهلاك" value={totals.dep} max={200000} unit="ر.س" tone="#A8432B" />
        <Gauge label="صافي القيمة الدفترية" value={totals.nbv} max={500000} unit="ر.س" tone="#B98B4E" />
      </div>
      <div className="panel">
        <h3>سجل الأصول الثابتة (حتى 2026-07-20)</h3>
        <table className="ledger-table">
          <thead><tr><th>الأصل</th><th>التصنيف</th><th>الشركة</th><th>التكلفة</th><th>مجمع الإهلاك</th><th>صافي القيمة الدفترية</th><th>الحالة</th></tr></thead>
          <tbody>
            {list.map((a) => {
              const dep = assetAccumulatedDepreciation(a, "2026-07-20");
              return (
                <tr key={a.id}>
                  <td>{a.name}</td><td>{a.category}</td><td>{COMPANIES.find((c) => c.id === a.company)?.short}</td>
                  <td className="num">{fmt(a.cost)}</td><td className="num">{fmt(dep)}</td><td className="num strong">{fmt(a.cost - dep)}</td>
                  <td>{a.status === "disposed" ? "مستبعد" : "نشط"}</td>
                </tr>
              );
            })}
          </tbody>
          <tfoot><tr><td className="foot-label" colSpan={3}>الإجمالي</td><td className="num strong">{fmt(totals.cost)}</td><td className="num strong">{fmt(totals.dep)}</td><td className="num strong">{fmt(totals.nbv)}</td><td></td></tr></tfoot>
        </table>
        {list.length === 0 && <p className="empty">لا توجد أصول مسجّلة بعد.</p>}
      </div>
    </div>
  );
}

const FIXED_ASSETS_TABS = [
  { id: "register", label: "سجل الأصول" },
  { id: "depreciation", label: "الإهلاك" },
  { id: "disposal", label: "الاستبعاد / البيع" },
  { id: "reports", label: "التقارير" },
];

function FixedAssetsModule({ assets, setAssets, depreciationRuns, setDepreciationRuns, entries, setEntries, companyId, tab, setTab }) {
  return (
    <div>
      <div className="section-title"><span className="eyebrow">إدارة الممتلكات</span><h2>الأصول الثابتة</h2></div>
      <div className="report-tabs">{FIXED_ASSETS_TABS.map((t) => (<button key={t.id} className={"report-tab" + (tab === t.id ? " active" : "")} onClick={() => setTab(t.id)}>{t.label}</button>))}</div>
      {tab === "register" && <AssetRegisterModule assets={assets} setAssets={setAssets} entries={entries} setEntries={setEntries} companyId={companyId} />}
      {tab === "depreciation" && <DepreciationModule assets={assets} depreciationRuns={depreciationRuns} setDepreciationRuns={setDepreciationRuns} entries={entries} setEntries={setEntries} companyId={companyId} />}
      {tab === "disposal" && <DisposalModule assets={assets} setAssets={setAssets} entries={entries} setEntries={setEntries} companyId={companyId} />}
      {tab === "reports" && <AssetReportsModule assets={assets} companyId={companyId} />}
    </div>
  );
}

