function LoginPage({ users, onLoginSuccess, onGoLanding, onGoRegister }) {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");

  const submit = () => {
    const user = users.find((u) => u.email.toLowerCase() === email.trim().toLowerCase());
    if (!user || !user.password) { setError("البريد الإلكتروني أو كلمة المرور غير صحيحة."); return; }
    if (user.password !== password) { setError("البريد الإلكتروني أو كلمة المرور غير صحيحة."); return; }
    if (!user.active) { setError("هذا الحساب معطّل حالياً — تواصل مع مدير النظام."); return; }
    setError("");
    onLoginSuccess(user);
  };

  return (
    <div className="auth-root">
      <div className="auth-card">
        <div className="landing-brand auth-brand">
          <div className="brand-mark landing-mark"><span className="brand-mark-needle" style={{ background: "#B98B4E" }} /></div>
          <span>أثر المحاسبي</span>
        </div>
        <h2 className="auth-title">تسجيل الدخول</h2>
        <div className="auth-form">
          <label>البريد الإلكتروني<input type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="name@company.sa" /></label>
          <label>كلمة المرور<input type="password" value={password} onChange={(e) => setPassword(e.target.value)} onKeyDown={(e) => e.key === "Enter" && submit()} /></label>
          {error && <p className="balance-bad">{error}</p>}
          <button className="btn-primary auth-submit" onClick={submit}>دخول</button>
        </div>
        <div className="auth-links">
          <button className="link-btn" onClick={onGoRegister}>ليس لديك حساب؟ سجّل الآن</button>
          <button className="link-btn" onClick={onGoLanding}>الرجوع للصفحة الرئيسية</button>
        </div>
        <p className="note auth-note">هذه بيئة عرض تجريبية — بيانات الدخول لا تُخزَّن أو تُشفَّر على خادم حقيقي، ولا تُستخدم لبيانات حساسة فعلية.</p>
      </div>
    </div>
  );
}

function RegisterPage({ setUsers, onRegisterSuccess, onGoLanding, onGoLogin }) {
  const [companyName, setCompanyName] = useState("");
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [error, setError] = useState("");

  const submit = () => {
    if (!companyName || !name || !email || !password) { setError("يرجى تعبئة كل الحقول."); return; }
    if (password !== confirmPassword) { setError("كلمتا المرور غير متطابقتين."); return; }
    setError("");
    const newUser = { id: Date.now(), name, email, password, role: "مدير مالي", company: "all", active: true, inviteStatus: "accepted", trialStart: "2026-07-20" };
    setUsers((prev) => [...prev, newUser]);
    onRegisterSuccess(newUser);
  };

  return (
    <div className="auth-root">
      <div className="auth-card">
        <div className="landing-brand auth-brand">
          <div className="brand-mark landing-mark"><span className="brand-mark-needle" style={{ background: "#B98B4E" }} /></div>
          <span>أثر المحاسبي</span>
        </div>
        <h2 className="auth-title">ابدأ تجربتك المجانية لمدة شهر</h2>
        <div className="auth-form">
          <label>اسم الشركة / المنشأة<input type="text" value={companyName} onChange={(e) => setCompanyName(e.target.value)} /></label>
          <label>الاسم الكامل<input type="text" value={name} onChange={(e) => setName(e.target.value)} /></label>
          <label>البريد الإلكتروني<input type="email" value={email} onChange={(e) => setEmail(e.target.value)} /></label>
          <label>كلمة المرور<input type="password" value={password} onChange={(e) => setPassword(e.target.value)} /></label>
          <label>تأكيد كلمة المرور<input type="password" value={confirmPassword} onChange={(e) => setConfirmPassword(e.target.value)} /></label>
          {error && <p className="balance-bad">{error}</p>}
          <button className="btn-primary auth-submit" onClick={submit}>إنشاء الحساب وبدء التجربة</button>
        </div>
        <div className="auth-links">
          <button className="link-btn" onClick={onGoLogin}>لديك حساب بالفعل؟ سجّل الدخول</button>
          <button className="link-btn" onClick={onGoLanding}>الرجوع للصفحة الرئيسية</button>
        </div>
        <p className="note auth-note">
          هذه بيئة عرض تجريبية لا ترتبط بخادم حقيقي أو قاعدة بيانات فعلية؛ التسجيل هنا لأغراض العرض فقط، ولا يُنشئ فعلياً
          عزلاً كاملاً للبيانات بين المنشآت كما سيحدث في الإصدار الإنتاجي الفعلي.
        </p>
      </div>
    </div>
  );
}

